  const coverage = input.phaseOne.universe.eventCoverage;
  const gaps: ReceivablesMethodReadinessGap[] = [
    gap("portfolio_lineage_not_assembled", "portfolio_lineage", "evidence", "A carteira calculada ainda não foi ligada, título a título, ao contrato de entrada do método especialista.", "The calculated pool has not yet been linked title by title to the specialist method input contract.", "Confirme o mapeamento entre cada linha da carteira conciliada e cada título que deverá integrar a base elegível.", "Confirm the mapping between every reconciled pool row and every receivable that should enter the eligible base.", evidenceIds),
    gap("cedent_and_servicing_not_evidenced", "cedent_and_servicing", "evidence", "Identidade do cedente e responsabilidade de servicing ainda não estão comprovadas no contrato do método.", "Cedent identity and servicing responsibility are not yet evidenced in the method contract.", "Quem é o titular dos créditos e quem fará cobrança, conciliação e substituição da carteira durante a operação?", "Who owns the receivables and who will service, reconcile and replace the pool during the facility?", evidenceIds),
    gap("title_legal_controls_not_evidenced", "title_legal_controls", "evidence", "Cessão, existência, registro, ônus, disputas e partes relacionadas não estão comprovados título a título.", "Assignment, existence, registration, liens, disputes and related parties are not evidenced title by title.", "Envie a evidência de lastro e o controle por título de cessão, registro, ônus, disputa e parte relacionada.", "Provide title-level evidence of existence, assignment, registration, liens, disputes and related parties.", evidenceIds),
    gap("cash_reconciliation_not_evidenced", "cash_reconciliation", "evidence", "Os recebimentos não estão reconciliados com extrato, conta vinculada e controle de duplicidades.", "Cash receipts are not reconciled to bank evidence, linked accounts and duplicate controls.", "Envie o extrato e o arquivo de baixas que permitam ligar cada recebimento ao título, identificar duplicidades e comprovar a conta de recebimento.", "Provide bank and settlement files that link each receipt to a title, identify duplicates and evidence the collection account.", evidenceIds),
    gap("accounting_reconciliation_not_evidenced", "accounting_reconciliation", "evidence", "Saldo bruto, provisão e recebimentos contábeis ainda não foram ligados à mesma data-base da carteira.", "Gross balance, allowance and accounting collections are not yet tied to the pool reporting date.", "Envie o razão ou balancete da data-base com contas a receber, provisão e baixas para conciliarmos com a carteira.", "Provide the reporting-date ledger or trial balance for receivables, allowance and collections so it can be tied to the pool.", evidenceIds),
    gap("eligibility_policy_not_governed", "eligibility_policy", "policy", "Os critérios e limites da base elegível ainda não foram definidos ou aprovados como premissas do caso.", "Eligibility criteria and limits have not been defined or approved as case assumptions.", "Quais critérios devemos testar para atraso, prazo, concentração, lastro, registro, ônus, diluição, recompra, perdas e cobertura mínima?", "Which criteria should be tested for delinquency, tenor, concentration, evidence, registration, liens, dilution, repurchases, losses and minimum coverage?"),
    gap("facility_and_waterfall_not_governed", "facility_and_waterfall", "structure", "Valor, advance rate, sobrecolateralização, subordinação, reserva e waterfall não estão definidos no contrato do método.", "Facility amount, advance rate, overcollateralization, subordination, reserve and waterfall are not defined in the method contract.", "Qual estrutura devemos simular: valor, advance rate, sobrecolateralização, subordinação, reserva e prioridades do fluxo de caixa?", "Which structure should be simulated: amount, advance rate, overcollateralization, subordination, reserve and cash-flow priorities?"),
  ];
  const incompleteEvents = Object.entries(coverage).filter(([, value]) => value.status !== "complete");
  if (incompleteEvents.length > 0) {
    gaps.push(gap(
      "performance_history_incomplete",
      "performance_history",
      "evidence",
      `O histórico está incompleto para: ${incompleteEvents.map(([name]) => name).join(", ")}. Ausência de evento não será tratada como zero.`,
      `History is incomplete for: ${incompleteEvents.map(([name]) => name).join(", ")}. Missing events will not be treated as zero.`,
      "Envie os históricos completos de liquidação, diluição, prorrogação, recompra, substituição e cessões/ônus para o período analisado.",
      "Provide complete settlement, dilution, extension, repurchase, substitution and assignment/lien histories for the analysis period.",
      evidenceIds,
    ));
  }
  return gaps;
};

const decimalEqual = (left: string, right: string) => new Decimal(left).eq(right);

function assemblyConflicts(
  phaseOne: ReceivablesPhaseOneInput,
  detection: ReceivablesRawDetectionReport,
  assembly: ReceivablesPoolInputAssembly,
): ReceivablesMethodReadinessGap[] {
  const gaps: ReceivablesMethodReadinessGap[] = [];
  const source = phaseOne.universe;
  const method = assembly.input.case;
  const conflict = (code: string, pt: string, en: string) => gaps.push(gap(code, "portfolio_lineage", "conflict", pt, en, "Revise a montagem do input e confirme qual valor e fonte devem prevalecer antes da execução.", "Review the input assembly and confirm which value and source should prevail before execution."));
  if (assembly.source.datasetHash !== phaseOne.datasetHash) conflict("source_dataset_hash_mismatch", "O input montado aponta para outra versão da carteira.", "The assembled input points to a different pool version.");
  if (assembly.source.universeId !== source.id) conflict("source_universe_mismatch", "O input montado aponta para outro universo de recebíveis.", "The assembled input points to a different receivables universe.");
  if (method.referenceDate !== source.dates.reportingDate) conflict("reference_date_mismatch", "A data-base do método diverge da carteira conciliada.", "The method reporting date differs from the reconciled pool.");
  if (assembly.input.currency !== source.currency || method.portfolio.some((item) => assembly.input.currency !== source.currency)) conflict("currency_mismatch", "A moeda do método diverge da carteira conciliada.", "The method currency differs from the reconciled pool.");

  const methodById = new Map(method.portfolio.map((item) => [item.id, item]));
  const sourceById = new Map(source.receivables.map((item) => [item.id, item]));
  const mappedSourceIds = new Set(assembly.source.titleMapping.map((item) => item.sourceReceivableId));
  const mappedMethodIds = new Set(assembly.source.titleMapping.map((item) => item.methodReceivableId));
  if (mappedSourceIds.size !== source.receivables.length || source.receivables.some((item) => !mappedSourceIds.has(item.id))) conflict("source_title_mapping_incomplete", "Nem todos os títulos da carteira de origem foram mapeados.", "Not every source pool title was mapped.");
  if (mappedMethodIds.size !== method.portfolio.length || method.portfolio.some((item) => !mappedMethodIds.has(item.id))) conflict("method_title_mapping_incomplete", "O input do método contém título sem ligação com a carteira de origem.", "The method input contains a title not linked to the source pool.");
  for (const mapping of assembly.source.titleMapping) {
    const sourceTitle = sourceById.get(mapping.sourceReceivableId);
    const methodTitle = methodById.get(mapping.methodReceivableId);
    if (!sourceTitle || !methodTitle) continue;
    if (
      sourceTitle.issueDate !== methodTitle.originDate
      || sourceTitle.currentDueDate !== methodTitle.dueDate
      || sourceTitle.obligorId !== methodTitle.debtorId
      || !decimalEqual(sourceTitle.faceValue, methodTitle.originalAmount)
      || !decimalEqual(sourceTitle.openValue, methodTitle.outstandingBalance)
    ) {
      conflict("mapped_title_economics_mismatch", `O título ${sourceTitle.id} mudou em valor, data ou sacado durante a montagem do input.`, `Title ${sourceTitle.id} changed in amount, date or obligor during input assembly.`);
      break;
    }
  }
  const resolvedFindingIds = new Set(assembly.findingResolutions.map((item) => item.findingId));
  const detectedFindingIds = new Set(detection.defects.map((item) => item.id));
  for (const resolution of assembly.findingResolutions) {
    if (!detectedFindingIds.has(resolution.findingId)) {
      gaps.push(gap(
        `finding_resolution_without_detection:${resolution.findingId}`,
        "title_legal_controls",
        "conflict",
        `Há um tratamento para o achado “${resolution.findingId}”, mas esse achado não pertence à detecção desta carteira.`,
        `A disposition exists for finding “${resolution.findingId}”, but that finding does not belong to this pool detection.`,
        "Confirme se a resolução pertence a outra versão da carteira e remova ou vincule o achado correto.",
        "Confirm whether the resolution belongs to another pool version and remove it or link the correct finding.",
      ));
    }
  }
  for (const finding of detection.defects) {
    if (!resolvedFindingIds.has(finding.id)) {
      gaps.push(gap(
        `finding_unresolved:${finding.id}`,
        "title_legal_controls",
        "conflict",
        `O achado “${finding.description}” ainda não tem tratamento evidenciado no input do método.`,
        `The finding “${finding.description}” has no evidenced treatment in the method input.`,
        "Confirme se o achado foi corrigido, se é falso positivo ou como foi incorporado aos critérios da análise, anexando a evidência.",
        "Confirm whether the finding was remediated, is a false positive or was incorporated into the analysis criteria, with supporting evidence.",
        finding.evidence.flatMap((entry) => entry.kind === "measured" ? entry.anchors.map((anchor) => anchor.kind === "file" ? anchor.fileId : anchor.kind === "document" ? anchor.documentId : anchor.eventId) : []),
      ));
    }
  }
  return gaps;
}

function primaryReason(gaps: readonly ReceivablesMethodReadinessGap[]): ReceivablesPoolMethodReadiness["primaryReason"] {
  if (gaps.some((item) => item.class === "conflict")) return "conflicting";
  if (gaps.some((item) => item.class === "evidence")) return "needs_evidence";
  if (gaps.some((item) => item.class === "policy")) return "needs_policy";
  if (gaps.some((item) => item.class === "structure")) return "needs_structure";
  return "ready";
}

/**
 * Fail-closed bridge between the immutable document rail and specialist execution. It never
 * fills a blank, interprets missing event history as zero or lets a valid-looking method payload
 * execute without a one-to-one source reconciliation and section-level evidence.
 */
export function assessReceivablesPoolMethodReadiness(input: ReadinessInput): ReceivablesPoolMethodReadiness {
  let gaps: ReceivablesMethodReadinessGap[];
  let validatedInput: ReceivablesPoolUnderwritingInput | null = null;
  const parsed = input.assembly === undefined ? null : receivablesPoolInputAssemblySchema.safeParse(input.assembly);
  if (!parsed?.success) {
    gaps = missingAssemblyGaps(input);
    if (parsed && !parsed.success) {
      gaps.unshift(gap("input_assembly_invalid", "portfolio_lineage", "conflict", "A montagem recebida não atende ao contrato governado do método.", "The received assembly does not satisfy the governed method contract.", "Revise os campos inválidos antes de tentar executar a análise especialista.", "Correct the invalid fields before attempting specialist execution."));
    }
  } else {
    gaps = assemblyConflicts(input.phaseOne, input.detection, parsed.data);
    if (gaps.length === 0) validatedInput = parsed.data.input;
  }
  const periodGroups = new Map<string, Set<string>>();
  for (const entry of input.detection.supportPeriodAssessment?.entries ?? []) {
    if (!supportPeriodBlocks(entry)) continue;
    const sources = periodGroups.get(entry.detectorId) ?? new Set<string>();
    sources.add(entry.sourceId);
    periodGroups.set(entry.detectorId, sources);
  }
  const periodGaps = [...periodGroups].sort(([a], [b]) => a.localeCompare(b)).map(([detectorId, sources]) => {
    const reviewOnly = input.detection.supportPeriodAssessment?.entries
      .filter((entry) => entry.detectorId === detectorId && supportPeriodBlocks(entry))
      .every((entry) => entry.requiresSourceReview === true);
    return gap(`support_period:${detectorId}`, detectorId === "cancelled_invoice_open" ? "title_legal_controls" : "accounting_reconciliation", "evidence",
      reviewOnly ? "Data e coluna de saldo dos documentos recebidos ainda precisam ser conferidas." : "O período ou valor da evidência de apoio não está qualificado para a data de corte.",
      reviewOnly ? "The dates and balance columns in the received documents still require review." : "The supporting evidence period or amount is not qualified for the reporting cutoff.",
      reviewOnly ? "Conferir data e coluna de saldo nos documentos recebidos." : "Confirme períodos e valores na fonte e forneça evidência compatível com a data de corte.",
      reviewOnly ? "Review dates and balance columns in the received documents." : "Confirm source periods and amounts and provide evidence compatible with the reporting cutoff.", [...sources]);
  });
  gaps = [...periodGaps, ...gaps];
  if (gaps.length > 0) validatedInput = null;
  const reason = primaryReason(gaps);
  const dimensions = dimensionOrder.map((id) => {
    const dimensionGaps = gaps.filter((item) => item.dimensionId === id);
    return {
      id,
      state: (dimensionGaps.some((item) => item.class === "conflict") ? "conflicting" : dimensionGaps.length > 0 ? "missing" : "satisfied") as "satisfied" | "missing" | "conflicting",
      gapCodes: dimensionGaps.map((item) => item.code).sort(),
    };
  });
  return {
    version: receivablesPoolMethodReadinessVersion,
    state: gaps.length === 0 ? "ready" : "blocked",
    primaryReason: reason,
    methodExecutionAllowed: gaps.length === 0,
    sourceDatasetHash: input.phaseOne.datasetHash,
    dimensions,
    gaps,
    nextQuestions: gaps.map((item) => ({id: item.code, dimensionId: item.dimensionId, text: item.question, evidenceIds: item.evidenceIds})),
    validatedInput,
  };
}

import {createHash} from "node:crypto";

import {z} from "zod";

import {eligibilityPolicySchema, receivablesStructureSchema} from "./schema";
import {
  receivablesCashSupplementSchema,
  receivablesMethodEvidenceReferenceSchema,
  receivablesMethodEvidenceSectionSchema,
  receivablesPoolInputSupplementSchema,
  receivablesPoolInputSupplementVersion,
  receivablesTitleSupplementSchema,
  type ReceivablesPoolInputSupplement,
} from "./method-assembly";

export const receivablesSupplementDraftVersion = "2026.09.07-v1" as const;
export const receivablesSupplementPatchVersion = "2026.09.07-v1" as const;

const sha256Schema = z.string().regex(/^[a-f0-9]{64}$/);
const cedentSchema = receivablesPoolInputSupplementSchema.shape.cedent;
const accountingSchema = receivablesPoolInputSupplementSchema.shape.accounting;
const findingResolutionSchema = receivablesPoolInputSupplementSchema.shape.findingResolutions.element;

const supplementFieldPaths = [
  "/policy/maxDaysPastDue", "/policy/maxRemainingTermDays", "/policy/minSeasoningDays",
  "/policy/requireAssignable", "/policy/requireEvidenceVerified", "/policy/registrationRule",
  "/policy/excludeDisputed", "/policy/excludeRelatedParties", "/policy/excludeEncumbered",
  "/policy/allowedDebtorSectors", "/policy/maxSingleDebtorShare", "/policy/maxDebtorGroupShare",
  "/policy/minimumEligibleShare", "/policy/minimumEvidenceCoverage", "/policy/minimumRegistrationCoverage",
  "/policy/maximumDelinquency30Share", "/policy/maximumDilutionShare", "/policy/maximumRepurchaseShare",
  "/policy/minimumRecoveryRate", "/policy/maximumAccountingMismatchShare", "/policy/maximumCashMismatchShare",
  "/policy/minimumMappedCashShare", "/policy/minimumLinkedAccountCashShare",
  "/structure/requestedFacility", "/structure/advanceRate", "/structure/requiredOvercollateralization",
  "/structure/requiredSubordinationRate", "/structure/actualSeniorAmount", "/structure/actualMezzanineAmount",
  "/structure/actualSubordinatedAmount", "/structure/reserveRate",
  "/structure/waterfall/availableCash", "/structure/waterfall/servicingFeeDue",
  "/structure/waterfall/seniorInterestDue", "/structure/waterfall/seniorPrincipalDue",
  "/structure/waterfall/reserveOpening", "/structure/waterfall/mezzanineDue",
] as const;
export const receivablesSupplementFieldPathSchema = z.enum(supplementFieldPaths);
export type ReceivablesSupplementFieldPath = z.infer<typeof receivablesSupplementFieldPathSchema>;

const policyFieldSchemas = eligibilityPolicySchema.shape as Record<string, z.ZodType>;
const structureFieldSchemas = receivablesStructureSchema.shape as Record<string, z.ZodType>;
const waterfallFieldSchemas = receivablesStructureSchema.shape.waterfall.shape as Record<string, z.ZodType>;

function fieldValueSchema(path: ReceivablesSupplementFieldPath): z.ZodType {
  const parts = path.split("/").filter(Boolean);
  const schema = parts[0] === "policy"
    ? policyFieldSchemas[parts[1]!]
    : parts[1] === "waterfall"
    ? waterfallFieldSchemas[parts[2]!]
    : structureFieldSchemas[parts[1]!];
  if (!schema) throw new Error(`receivables_supplement_field_schema_missing:${path}`);
  return schema;
}

function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (value !== null && typeof value === "object") {
    return `{${Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, nested]) => `${JSON.stringify(key)}:${stableJson(nested)}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

function fingerprint(value: unknown): string {
  return createHash("sha256").update(stableJson(value)).digest("hex");
}

function sectionPatch<T extends z.ZodType>(schema: T) {
  return z.object({
    value: schema,
    supersedesFingerprint: sha256Schema.optional(),
  }).strict();
}

const fieldPatchSchema = z.object({
  path: receivablesSupplementFieldPathSchema,
  value: z.unknown(),
  supersedesFingerprint: sha256Schema.optional(),
}).strict().superRefine((field, context) => {
  const parsed = fieldValueSchema(field.path).safeParse(field.value);
  if (!parsed.success) context.addIssue({code: "custom", path: ["value"], message: `invalid value for ${field.path}`});
});

const evidencePatchSchema = z.object({
  cedentAndServicing: receivablesMethodEvidenceSectionSchema.optional(),
  titleLegalControls: receivablesMethodEvidenceSectionSchema.optional(),
  performanceHistory: receivablesMethodEvidenceSectionSchema.optional(),
  cashReconciliation: receivablesMethodEvidenceSectionSchema.optional(),
  accountingReconciliation: receivablesMethodEvidenceSectionSchema.optional(),
  eligibilityPolicy: receivablesMethodEvidenceSectionSchema.optional(),
  facilityAndWaterfall: receivablesMethodEvidenceSectionSchema.optional(),
}).strict();

export const receivablesSupplementPatchSchema = z.object({
  schemaVersion: z.literal(receivablesSupplementPatchVersion),
  patchId: z.string().min(1).max(160),
  sourceDatasetHash: sha256Schema,
  suppliedBy: z.object({
    actorType: z.enum(["document_worker", "user", "system"]),
    actorId: z.string().min(1),
    suppliedAt: z.string().datetime({offset: true}),
    evidence: z.array(receivablesMethodEvidenceReferenceSchema).min(1),
  }).strict(),
  sections: z.object({
    cedent: sectionPatch(cedentSchema).optional(),
    titles: sectionPatch(z.array(receivablesTitleSupplementSchema).min(1)).optional(),
    cashReceipts: sectionPatch(z.array(receivablesCashSupplementSchema)).optional(),
    accounting: sectionPatch(accountingSchema).optional(),
    policy: sectionPatch(eligibilityPolicySchema).optional(),
    structure: sectionPatch(receivablesStructureSchema).optional(),
    findingResolutions: sectionPatch(z.array(findingResolutionSchema)).optional(),
  }).strict(),
  fields: z.array(fieldPatchSchema).max(supplementFieldPaths.length).default([]),
  evidence: evidencePatchSchema,
}).strict().superRefine((patch, context) => {
  const has = (key: keyof typeof patch.evidence) => patch.evidence[key] !== undefined;
  const requireEvidence = (condition: boolean, keys: (keyof typeof patch.evidence)[], path: string) => {
    if (condition && keys.some((key) => !has(key))) {
      context.addIssue({code: "custom", path: ["evidence", path], message: `section ${path} requires its governed evidence`});
    }
  };
  requireEvidence(Boolean(patch.sections.cedent), ["cedentAndServicing"], "cedentAndServicing");
  requireEvidence(Boolean(patch.sections.titles), ["titleLegalControls", "performanceHistory"], "titleLegalControls");
  requireEvidence(Boolean(patch.sections.cashReceipts), ["cashReconciliation"], "cashReconciliation");
  requireEvidence(Boolean(patch.sections.accounting), ["accountingReconciliation"], "accountingReconciliation");
  requireEvidence(Boolean(patch.sections.policy), ["eligibilityPolicy"], "eligibilityPolicy");
  requireEvidence(Boolean(patch.sections.structure), ["facilityAndWaterfall"], "facilityAndWaterfall");
  requireEvidence(patch.fields.some((field) => field.path.startsWith("/policy/")), ["eligibilityPolicy"], "eligibilityPolicy");
  requireEvidence(patch.fields.some((field) => field.path.startsWith("/structure/")), ["facilityAndWaterfall"], "facilityAndWaterfall");
  if (new Set(patch.fields.map((field) => field.path)).size !== patch.fields.length) {
    context.addIssue({code: "custom", path: ["fields"], message: "one value per field path is allowed in a patch"});
  }
  if (Object.keys(patch.sections).length === 0 && patch.fields.length === 0) {
    context.addIssue({code: "custom", path: ["sections"], message: "a patch must contribute at least one section"});
  }
});
export type ReceivablesSupplementPatch = z.infer<typeof receivablesSupplementPatchSchema>;

const sectionNames = ["cedent", "titles", "cashReceipts", "accounting", "policy", "structure", "findingResolutions"] as const;
type SectionName = typeof sectionNames[number];

const storedSectionSchema = z.object({
  value: z.unknown(),
  fingerprint: sha256Schema,
  patchIds: z.array(z.string().min(1)).min(1),
  sources: z.array(receivablesMethodEvidenceReferenceSchema).min(1),
}).strict();

export const receivablesSupplementDraftSchema = z.object({
  schemaVersion: z.literal(receivablesSupplementDraftVersion),
  sourceDatasetHash: sha256Schema,
  revision: z.number().int().nonnegative(),
  appliedPatchIds: z.array(z.string().min(1)),
  sections: z.object({
    cedent: storedSectionSchema.optional(),
    titles: storedSectionSchema.optional(),
    cashReceipts: storedSectionSchema.optional(),
    accounting: storedSectionSchema.optional(),
    policy: storedSectionSchema.optional(),
    structure: storedSectionSchema.optional(),
    findingResolutions: storedSectionSchema.optional(),
  }).strict(),
  fields: z.partialRecord(receivablesSupplementFieldPathSchema, storedSectionSchema).default({}),
  evidence: evidencePatchSchema,
  conflicts: z.array(z.object({
    id: sha256Schema,
    section: z.union([z.enum(sectionNames), receivablesSupplementFieldPathSchema]),
    status: z.enum(["open", "resolved"]),
    existingFingerprint: sha256Schema,
    incomingFingerprint: sha256Schema,
    incomingPatchId: z.string().min(1),
    resolvedByPatchId: z.string().min(1).nullable(),
  }).strict()),
}).strict();
export type ReceivablesSupplementDraft = z.infer<typeof receivablesSupplementDraftSchema>;

export function newReceivablesSupplementDraft(sourceDatasetHash: string): ReceivablesSupplementDraft {
  return receivablesSupplementDraftSchema.parse({
    schemaVersion: receivablesSupplementDraftVersion,
    sourceDatasetHash,
    revision: 0,
    appliedPatchIds: [],
    sections: {},
    fields: {},
    evidence: {},
    conflicts: [],
  });
}

function mergeEvidence(
  current: ReceivablesSupplementDraft["evidence"],
  incoming: ReceivablesSupplementPatch["evidence"],
): ReceivablesSupplementDraft["evidence"] {
  const merged: Record<string, unknown> = {...current};
  for (const [key, references] of Object.entries(incoming)) {
    const existing = (current as Record<string, unknown>)[key];
    const combined = [...(Array.isArray(existing) ? existing : []), ...(references ?? [])];
    merged[key] = [...new Map(combined.map((reference) => [stableJson(reference), reference])).values()]
      .sort((left, right) => stableJson(left).localeCompare(stableJson(right)));
  }
  return evidencePatchSchema.parse(merged);
}

/**
 * Applies sparse document or conversation facts without last-write-wins. A changed value becomes
 * an open conflict unless the patch names the exact fingerprint it supersedes. This lets a later
 * chat turn correct a premise while preserving who changed what and why.
 */
export function applyReceivablesSupplementPatch(input: {
  draft: unknown;
  patch: unknown;
}): ReceivablesSupplementDraft {
  const draft = receivablesSupplementDraftSchema.parse(input.draft);
  const patch = receivablesSupplementPatchSchema.parse(input.patch);
  if (patch.sourceDatasetHash !== draft.sourceDatasetHash) throw new Error("receivables_supplement_patch_dataset_mismatch");
  if (draft.appliedPatchIds.includes(patch.patchId)) return draft;

  const next = structuredClone(draft);
  next.revision += 1;
  next.appliedPatchIds.push(patch.patchId);
  next.appliedPatchIds.sort();
  next.evidence = mergeEvidence(next.evidence, patch.evidence);

  for (const section of sectionNames) {
    const incoming = patch.sections[section];
    if (!incoming) continue;
    if ((section === "policy" || section === "structure")
      && Object.keys(next.fields).some((path) => path.startsWith(`/${section}/`))) {
      throw new Error(`receivables_supplement_${section}_has_incremental_fields`);
    }
    const incomingFingerprint = fingerprint(incoming.value);
    const existing = next.sections[section];
    if (!existing) {
      next.sections[section] = {
        value: incoming.value,
        fingerprint: incomingFingerprint,
        patchIds: [patch.patchId],
        sources: patch.suppliedBy.evidence,
      };
      continue;
    }
    if (existing.fingerprint === incomingFingerprint) {
      existing.patchIds = [...new Set([...existing.patchIds, patch.patchId])].sort();
      existing.sources = [...new Map([...existing.sources, ...patch.suppliedBy.evidence]
        .map((reference) => [stableJson(reference), reference])).values()]
        .sort((left, right) => stableJson(left).localeCompare(stableJson(right)));
      continue;
    }
    if (incoming.supersedesFingerprint === existing.fingerprint) {
      next.sections[section] = {
        value: incoming.value,
        fingerprint: incomingFingerprint,
        patchIds: [patch.patchId],
        sources: patch.suppliedBy.evidence,
      };
      next.conflicts = next.conflicts.map((conflict) => conflict.section === section && conflict.status === "open"
        ? {...conflict, status: "resolved" as const, resolvedByPatchId: patch.patchId}
        : conflict);
      continue;
    }
    const conflictId = fingerprint({section, existing: existing.fingerprint, incoming: incomingFingerprint, patchId: patch.patchId});
    if (!next.conflicts.some((conflict) => conflict.id === conflictId)) {
      next.conflicts.push({
        id: conflictId,
        section,
        status: "open",
        existingFingerprint: existing.fingerprint,
        incomingFingerprint,
        incomingPatchId: patch.patchId,
        resolvedByPatchId: null,
      });
    }
  }
  for (const incoming of patch.fields) {
    const section = incoming.path.startsWith("/policy/") ? "policy" : "structure";
    if (next.sections[section]) throw new Error(`receivables_supplement_${section}_already_complete`);
    const incomingFingerprint = fingerprint(incoming.value);
    const existing = next.fields[incoming.path];
    if (!existing) {
      next.fields[incoming.path] = {
        value: incoming.value,
        fingerprint: incomingFingerprint,
        patchIds: [patch.patchId],
        sources: patch.suppliedBy.evidence,
      };
      continue;
    }
    if (existing.fingerprint === incomingFingerprint) {
      existing.patchIds = [...new Set([...existing.patchIds, patch.patchId])].sort();
      existing.sources = [...new Map([...existing.sources, ...patch.suppliedBy.evidence]
        .map((reference) => [stableJson(reference), reference])).values()]
        .sort((left, right) => stableJson(left).localeCompare(stableJson(right)));
      continue;
    }
    if (incoming.supersedesFingerprint === existing.fingerprint) {
      next.fields[incoming.path] = {
        value: incoming.value,
        fingerprint: incomingFingerprint,
        patchIds: [patch.patchId],
        sources: patch.suppliedBy.evidence,
      };
      next.conflicts = next.conflicts.map((conflict) => conflict.section === incoming.path && conflict.status === "open"
        ? {...conflict, status: "resolved" as const, resolvedByPatchId: patch.patchId}
        : conflict);
      continue;
    }
    const conflictId = fingerprint({section: incoming.path, existing: existing.fingerprint, incoming: incomingFingerprint, patchId: patch.patchId});
    if (!next.conflicts.some((conflict) => conflict.id === conflictId)) {
      next.conflicts.push({
        id: conflictId,
        section: incoming.path,
        status: "open",
        existingFingerprint: existing.fingerprint,
        incomingFingerprint,
        incomingPatchId: patch.patchId,
        resolvedByPatchId: null,
      });
    }
  }
  next.conflicts.sort((left, right) => left.id.localeCompare(right.id));
  return receivablesSupplementDraftSchema.parse(next);
}

export type ReceivablesSupplementDraftStatus = {
  state: "complete" | "incomplete" | "conflicted";
  missingSections: readonly string[];
  openConflictIds: readonly string[];
  supplement: ReceivablesPoolInputSupplement | null;
};

function incrementalGroup(draft: ReceivablesSupplementDraft, group: "policy" | "structure"): Record<string, unknown> {
  const value: Record<string, unknown> = {};
  for (const [path, field] of Object.entries(draft.fields)) {
    if (!path.startsWith(`/${group}/`) || !field) continue;
    const parts = path.split("/").filter(Boolean).slice(1);
    if (group === "structure" && parts[0] === "waterfall") {
      const waterfall = value.waterfall && typeof value.waterfall === "object" && !Array.isArray(value.waterfall)
        ? value.waterfall as Record<string, unknown>
        : {};
      waterfall[parts[1]!] = field.value;
      value.waterfall = waterfall;
    } else {
      value[parts[0]!] = field.value;
    }
  }
  return value;
}

function missingPaths(prefix: string, result: z.ZodSafeParseError<unknown>): string[] {
  return [...new Set(result.error.issues.map((issue) => `${prefix}.${issue.path.join(".") || "required"}`))].sort();
}

export function compileReceivablesSupplementDraft(input: unknown): ReceivablesSupplementDraftStatus {
  const draft = receivablesSupplementDraftSchema.parse(input);
  const openConflictIds = draft.conflicts.filter((conflict) => conflict.status === "open").map((conflict) => conflict.id).sort();
  const requiredSections: SectionName[] = ["cedent", "titles", "cashReceipts", "accounting"];
  const missingSections: string[] = requiredSections.filter((section) => !draft.sections[section]);
  const policy = eligibilityPolicySchema.safeParse(draft.sections.policy?.value ?? incrementalGroup(draft, "policy"));
  const structure = receivablesStructureSchema.safeParse(draft.sections.structure?.value ?? incrementalGroup(draft, "structure"));
  if (!policy.success) missingSections.push(...missingPaths("policy", policy));
  if (!structure.success) missingSections.push(...missingPaths("structure", structure));
  const requiredEvidence = [
    "cedentAndServicing", "titleLegalControls", "performanceHistory", "cashReconciliation",
    "accountingReconciliation", "eligibilityPolicy", "facilityAndWaterfall",
  ] as const;
  missingSections.push(...requiredEvidence.filter((section) => !draft.evidence[section]).map((section) => `evidence.${section}`));
  const uniqueMissingSections = [...new Set(missingSections)].sort();
  if (openConflictIds.length > 0) return {state: "conflicted", missingSections: uniqueMissingSections, openConflictIds, supplement: null};
  if (uniqueMissingSections.length > 0) return {state: "incomplete", missingSections: uniqueMissingSections, openConflictIds, supplement: null};

  const supplement = receivablesPoolInputSupplementSchema.parse({
    schemaVersion: receivablesPoolInputSupplementVersion,
    sourceDatasetHash: draft.sourceDatasetHash,
    cedent: draft.sections.cedent!.value,
    titles: draft.sections.titles!.value,
    cashReceipts: draft.sections.cashReceipts!.value,
    accounting: draft.sections.accounting!.value,
    policy: policy.success ? policy.data : null,
    structure: structure.success ? structure.data : null,
    evidence: draft.evidence,
    findingResolutions: draft.sections.findingResolutions?.value ?? [],
  });
  return {state: "complete", missingSections: [], openConflictIds: [], supplement};
}

