import {z} from "zod";
import type {ReceivablesEvidenceDocument, ReceivablesEvidenceTableRow} from "./raw-detection";

const anchorSchema = z.object({
  id: z.string().min(1).max(1024), text: z.string().max(512), truncated: z.literal(true).optional(),
  bbox: z.tuple([z.number().finite(), z.number().finite(), z.number().finite(), z.number().finite()]).nullable().optional(),
});
const roleSchema = z.enum(["closing_balance", "opening_balance", "debit", "credit", "outstanding_balance"]);
const contextKindSchema = z.enum(["period", "as_of", "issued_at", "entity", "perimeter", "unit"]);

/** These are source observations, never accepted facts or authority to calculate. */
export const balanceSourceProposalSchema = z.object({
  id: z.string().min(1), sourceId: z.string().min(1), sourceLabel: z.string().min(1),
  sourceHash: z.string().regex(/^[a-f0-9]{64}$/), documentVersion: z.number().int().positive().nullable(),
  containerId: z.string().min(1), page: z.number().int().positive().optional(), sheet: z.string().optional(),
  reviewState: z.literal("proposed"), calculationUse: z.literal("not_permitted"),
  columns: z.array(z.object({role: roleSchema, header: anchorSchema})).min(1).max(16),
  context: z.array(z.object({kind: contextKindSchema, anchor: anchorSchema})).max(32),
  rows: z.array(z.object({id: z.string().min(1), cells: z.array(anchorSchema).max(16)})).max(12),
  issues: z.array(z.enum(["review_required", "source_version_missing", "entity_not_identified", "perimeter_not_identified", "unit_not_identified", "economic_date_not_identified", "multiple_economic_date_references", "multiple_balance_columns", "column_geometry_unavailable", "source_context_unanchored", "source_rows_truncated", "source_context_truncated", "source_cells_truncated", "source_text_truncated"])),
});
export type BalanceSourceProposal = z.infer<typeof balanceSourceProposalSchema>;
export const balanceSourceAssessmentSchema = z.object({
  schemaVersion: z.literal("balance-source-proposals.v1"),
  reportingDate: z.iso.date(),
  proposals: z.array(balanceSourceProposalSchema).max(16),
  issues: z.array(z.literal("assessment_limit_reached")).max(1),
});
export type BalanceSourceAssessment = z.infer<typeof balanceSourceAssessmentSchema>;

const fold = (text: string) => text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/\s+/g, " ").trim();
const roles = new Map<string, z.infer<typeof roleSchema>>([
  ["saldo atual", "closing_balance"], ["saldo final", "closing_balance"], ["closing balance", "closing_balance"],
  ["saldo anterior", "opening_balance"], ["opening balance", "opening_balance"],
  ["debito", "debit"], ["debitos", "debit"], ["debit", "debit"],
  ["credito", "credit"], ["creditos", "credit"], ["credit", "credit"],
  ["saldo devedor", "outstanding_balance"], ["outstanding balance", "outstanding_balance"],
]);
type SourceText = {id?: string | undefined; text: string; bbox?: readonly [number, number, number, number] | null | undefined};
const anchor = (cell: SourceText & {id: string}): z.infer<typeof anchorSchema> => ({
  id: cell.id, text: cell.text.slice(0, 512), ...(cell.text.length > 512 ? {truncated: true as const} : {}),
  ...(cell.bbox === undefined ? {} : {bbox: cell.bbox === null ? null : [...cell.bbox] as [number, number, number, number]}),
});

function contextKinds(text: string): z.infer<typeof contextKindSchema>[] {
  const value = fold(text);
  return [
    ...(/\bperiodo\b|\bperiod\b/.test(value) ? ["period" as const] : []),
    ...(/\bdata[- ]?base\b|\bbase\s*:?\s*\d|\bas of\b/.test(value) ? ["as_of" as const] : []),
    ...(/\bemissao\b|\bemitido\b|\bissued\b/.test(value) ? ["issued_at" as const] : []),
    ...(/\bcnpj\b|\btax id\b/.test(value) ? ["entity" as const] : []),
    ...(/\bconsolidado\b|\bindividual\b|\bcontroladora\b|\bconsolidated\b|\bstandalone\b/.test(value) ? ["perimeter" as const] : []),
    ...(/\br\$|\breais\b|\bbrl\b|\busd\b|\beur\b|\bmilhares\b|\bthousands\b/.test(value) ? ["unit" as const] : []),
  ];
}

/**
 * Preserve all relevant competing declarations in their own source container. In
 * particular, issue date is not reporting date and an entity name is not a perimeter.
 * No cell is assigned to a balance column until a separate governed review exists.
 */
export function proposeBalanceSources(documents: readonly ReceivablesEvidenceDocument[], reportingDate: string): BalanceSourceAssessment {
  const proposals: BalanceSourceProposal[] = [];
  let limitReached = false;
  let payloadBytes = 0;
  for (const document of [...documents].sort((a, b) => a.id.localeCompare(b.id))) {
    if (limitReached) break;
    const add = (containerId: string, rows: readonly ReceivablesEvidenceTableRow[], context: readonly SourceText[], location: {page?: number; sheet?: string}) => {
      for (let index = 0; index < rows.length; index += 1) {
        if (limitReached) break;
        const header = rows[index]!;
        const allColumns = header.cells.flatMap((cell) => {
          const role = roles.get(fold(cell.text));
          return role ? [{role, header: anchor(cell)}] : [];
        });
        if (!allColumns.some((column) => column.role === "closing_balance" || column.role === "outstanding_balance")) continue;
        if (proposals.length >= 16) { limitReached = true; break; }
        const columns = allColumns.slice(0, 16);
        // A repeated header starts a new candidate; never inherit it across pages/tables.
        let end = index + 1;
        while (end < rows.length && !rows[end]!.cells.some((cell) => {
          const role = roles.get(fold(cell.text));
          return role === "closing_balance" || role === "outstanding_balance";
        })) end += 1;
        // Bound the scan itself, not only its output: repeated headers cannot multiply
        // an entire sheet prefix. Omitted context is explicit and never authorizes use.
        const contextTexts: SourceText[] = context.slice(0, 64);
        let contextTruncated = context.length > 64;
        let visited = 0;
        contextScan: for (let rowIndex = 0; rowIndex <= index; rowIndex += 1) {
          for (const cell of rows[rowIndex]!.cells) {
            if (visited >= 128) { contextTruncated = true; break contextScan; }
            contextTexts.push(cell); visited += 1;
          }
        }
        const observed = contextTexts.flatMap((cell) => cell.id ? contextKinds(cell.text).map((kind) => ({kind, anchor: anchor({...cell, id: cell.id!})})) : []);
        const unique = new Map(observed.map((item) => [`${item.kind}:${item.anchor.id}`, item]));
        const allContexts = [...unique.values()].sort((a, b) => a.kind.localeCompare(b.kind) || a.anchor.id.localeCompare(b.anchor.id));
        const contexts = allContexts.slice(0, 32);
        const has = (kind: z.infer<typeof contextKindSchema>) => contexts.some((item) => item.kind === kind);
        const issues: BalanceSourceProposal["issues"] = ["review_required"];
        if (!document.layer.documentVersion) issues.push("source_version_missing");
        if (!has("entity")) issues.push("entity_not_identified");
        if (!has("perimeter")) issues.push("perimeter_not_identified");
        if (!has("unit")) issues.push("unit_not_identified");
        const economic = contexts.filter((item) => item.kind === "period" || item.kind === "as_of");
        if (economic.length === 0) issues.push("economic_date_not_identified");
        if (economic.length > 1) issues.push("multiple_economic_date_references");
        if (new Set(columns.map((item) => item.role)).size !== columns.length) issues.push("multiple_balance_columns");
        if (location.page !== undefined && columns.some((column) => !column.header.bbox)) issues.push("column_geometry_unavailable");
        if (contextTexts.some((cell) => !cell.id && contextKinds(cell.text).length > 0)) issues.push("source_context_unanchored");
        const sourceRows = rows.slice(index + 1, end);
        if (contextTruncated || allContexts.length > 32) issues.push("source_context_truncated");
        if (allColumns.length > 16 || sourceRows.slice(0, 12).some((row) => row.cells.length > 16)) issues.push("source_cells_truncated");
        if ([...columns.map((column) => column.header), ...contexts.map((item) => item.anchor)].some((item) => item.truncated) || sourceRows.slice(0, 12).some((row) => row.cells.slice(0, 16).some((cell) => cell.text.length > 512))) issues.push("source_text_truncated");
        if (sourceRows.length > 12) issues.push("source_rows_truncated");
        const proposal: BalanceSourceProposal = {
          id: `${document.id}:${containerId}:${header.id}`, sourceId: document.id, sourceLabel: document.fileName,
          sourceHash: document.fileHash, documentVersion: document.layer.documentVersion ?? null, containerId, ...location,
          reviewState: "proposed", calculationUse: "not_permitted", columns, context: contexts,
          rows: sourceRows.slice(0, 12).map((row) => ({id: row.id, cells: row.cells.slice(0, 16).map(anchor)})), issues,
        };
        const bytes = new TextEncoder().encode(JSON.stringify(proposal)).byteLength;
        if (payloadBytes + bytes > 250_000) { limitReached = true; break; }
        payloadBytes += bytes; proposals.push(proposal);
      }
    };
    for (const page of document.layer.pages ?? []) {
      for (const table of page.tables) {
        // A container without a stable anchor cannot become a proposal.
        if (!table.id || !page.n) continue;
        add(table.id, table.rows, page.blocks, {page: page.n});
      }
    }
    for (const sheet of document.layer.sheets ?? []) {
      const grouped = new Map<number, {id: string; text: string; column: string}[]>();
      for (const cell of sheet.cells) {
        const match = /^([A-Z]{1,3})([1-9]\d{0,6})$/.exec(cell.ref);
        if (!match) continue;
        const row = Number(match[2]);
        if (!Number.isSafeInteger(row)) continue;
        const entries = grouped.get(row) ?? [];
        entries.push({id: `s${sheet.name}!${cell.ref}`, text: String(cell.v ?? ""), column: match[1]!});
        grouped.set(row, entries);
      }
      const ordinal = (column: string) => [...column].reduce((n, character) => n * 26 + character.charCodeAt(0) - 64, 0);
      const rows = [...grouped].sort(([a], [b]) => a - b).map(([n, cells]) => ({id: `s${sheet.name}!row${n}`, cells: cells.sort((a, b) => ordinal(a.column) - ordinal(b.column))}));
      add(`s${sheet.name}`, rows, [], {sheet: sheet.name});
    }
  }
  return balanceSourceAssessmentSchema.parse({schemaVersion: "balance-source-proposals.v1", reportingDate, proposals, issues: limitReached ? ["assessment_limit_reached"] : []});
}

packages/receivables-analysis/src/method.content:
import {supportPeriodBlocks} from "./support-periods";
import Decimal from "decimal.js";
import {z} from "zod";

import type {ReceivablesPhaseOneInput} from "./phase-one";
import type {ReceivablesRawDetectionReport} from "./raw-detection";
import {
  receivablesPoolUnderwritingInputSchema,
  type ReceivablesPoolUnderwritingInput,
} from "./underwrite";

export const receivablesPoolInputAssemblyVersion = "2026.09.07-v1" as const;
export const receivablesPoolMethodReadinessVersion = "2026.09.07-v1" as const;

const sha256Schema = z.string().regex(/^[a-f0-9]{64}$/);
const evidenceReferenceSchema = z.object({
  sourceClass: z.enum(["provided_document", "project_context", "house_method", "user_confirmation"]),
  sourceId: z.string().min(1),
  anchor: z.string().min(1),
}).strict();

const evidenceSectionSchema = z.array(evidenceReferenceSchema).min(1);

/**
 * The full method input is never accepted as an unattached JSON object. This envelope proves
 * which immutable title universe it came from, maps every source title one-to-one and requires
 * evidence for each judgement that the title tape alone cannot establish.
 */
export const receivablesPoolInputAssemblySchema = z.object({
  schemaVersion: z.literal(receivablesPoolInputAssemblyVersion),
  source: z.object({
    universeId: z.string().min(1),
    datasetHash: sha256Schema,
    titleMapping: z.array(z.object({
      sourceReceivableId: z.string().min(1),
      methodReceivableId: z.string().min(1),
    }).strict()).min(1),
  }).strict(),
  evidence: z.object({
    cedentAndServicing: evidenceSectionSchema,
    titleLegalControls: evidenceSectionSchema,
    performanceHistory: evidenceSectionSchema,
    cashReconciliation: evidenceSectionSchema,
    accountingReconciliation: evidenceSectionSchema,
    eligibilityPolicy: evidenceSectionSchema,
    facilityAndWaterfall: evidenceSectionSchema,
  }).strict(),
  findingResolutions: z.array(z.object({
    findingId: z.string().min(1),
    disposition: z.enum(["remediated", "false_positive", "incorporated_in_method_input"]),
    rationale: z.string().min(10),
    evidence: evidenceSectionSchema,
  }).strict()),
  input: receivablesPoolUnderwritingInputSchema,
}).strict().superRefine((assembly, context) => {
  const sourceIds = assembly.source.titleMapping.map((entry) => entry.sourceReceivableId);
  const methodIds = assembly.source.titleMapping.map((entry) => entry.methodReceivableId);
  if (new Set(sourceIds).size !== sourceIds.length) {
    context.addIssue({code: "custom", path: ["source", "titleMapping"], message: "source receivable mapping must be one-to-one"});
  }
  if (new Set(methodIds).size !== methodIds.length) {
    context.addIssue({code: "custom", path: ["source", "titleMapping"], message: "method receivable mapping must be one-to-one"});
  }
});
export type ReceivablesPoolInputAssembly = z.infer<typeof receivablesPoolInputAssemblySchema>;

export type ReceivablesMethodReadinessDimensionId =
  | "source_universe"
  | "portfolio_lineage"
  | "cedent_and_servicing"
  | "title_legal_controls"
  | "performance_history"
  | "cash_reconciliation"
  | "accounting_reconciliation"
  | "eligibility_policy"
  | "facility_and_waterfall";

export type ReceivablesMethodReadinessGapClass = "evidence" | "policy" | "structure" | "conflict";

export type ReceivablesMethodReadinessGap = {
  code: string;
  dimensionId: ReceivablesMethodReadinessDimensionId;
  class: ReceivablesMethodReadinessGapClass;
  blocking: true;
  message: {pt: string; en: string};
  question: {pt: string; en: string};
  evidenceIds: readonly string[];
};

export type ReceivablesPoolMethodReadiness = {
  version: typeof receivablesPoolMethodReadinessVersion;
  state: "ready" | "blocked";
  primaryReason: "ready" | "conflicting" | "needs_evidence" | "needs_policy" | "needs_structure";
  methodExecutionAllowed: boolean;
  sourceDatasetHash: string;
  dimensions: readonly {
    id: ReceivablesMethodReadinessDimensionId;
    state: "satisfied" | "missing" | "conflicting";
    gapCodes: readonly string[];
  }[];
  gaps: readonly ReceivablesMethodReadinessGap[];
  nextQuestions: readonly {
    id: string;
    dimensionId: ReceivablesMethodReadinessDimensionId;
    text: {pt: string; en: string};
    evidenceIds: readonly string[];
  }[];
  validatedInput: ReceivablesPoolUnderwritingInput | null;
};

type ReadinessInput = {
  phaseOne: ReceivablesPhaseOneInput;
  detection: ReceivablesRawDetectionReport;
  assembly?: unknown;
};

const dimensionOrder: readonly ReceivablesMethodReadinessDimensionId[] = [
  "source_universe",
  "portfolio_lineage",
  "cedent_and_servicing",
  "title_legal_controls",
  "performance_history",
  "cash_reconciliation",
  "accounting_reconciliation",
  "eligibility_policy",
  "facility_and_waterfall",
];

function gap(
  code: string,
  dimensionId: ReceivablesMethodReadinessDimensionId,
  gapClass: ReceivablesMethodReadinessGapClass,
  pt: string,
  en: string,
  questionPt: string,
  questionEn: string,
  evidenceIds: readonly string[] = [],
): ReceivablesMethodReadinessGap {
  return {code, dimensionId, class: gapClass, blocking: true, message: {pt, en}, question: {pt: questionPt, en: questionEn}, evidenceIds: [...new Set(evidenceIds)].sort()};
}

const missingAssemblyGaps = (input: ReadinessInput): ReceivablesMethodReadinessGap[] => {
  const evidenceIds = input.detection.evidenceCoverage.searchedEvidenceIds;
  const coverage = input.phaseOne.universe.eventCoverage;
  const gaps: ReceivablesMethodReadinessGap[] = [
    gap("portfolio_lineage_not_assembled", "portfolio_lineage", "evidence", "A carteira calculada ainda não foi ligada, título a título, ao contrato de entrada do método especialista.", "The calculated pool has not yet been linked title by title to the specialist method input contract.", "Confirme o mapeamento entre cada linha da carteira conciliada e cada título que deverá integrar a base elegível.", "Confirm the mapping between every reconciled pool row and every receivable that should enter the eligible base.", evidenceIds),
    gap("cedent_and_servicing_not_evidenced", "cedent_and_servicing", "evidence", "Identidade do cedente e responsabilidade de servicing ainda não estão comprovadas no contrato do método.", "Cedent identity and servicing responsibility are not yet evidenced in the method contract.", "Quem é o titular dos créditos e quem fará cobrança, conciliação e substituição da carteira durante a operação?", "Who owns the receivables and who will service, reconcile and replace the pool during the facility?", evidenceIds),
    gap("title_legal_controls_not_evidenced", "title_legal_controls", "evidence", "Cessão, existência, registro, ônus, disputas e partes relacionadas não estão comprovados título a título.", "Assignment, existence, registration, liens, disputes and related parties are not evidenced title by title.", "Envie a evidência de lastro e o controle por título de cessão, registro, ônus, disputa e parte relacionada.", "Provide title-level evidence of existence, assignment, registration, liens, disputes and related parties.", evidenceIds),
    gap("cash_reconciliation_not_evidenced", "cash_reconciliation", "evidence", "Os recebimentos não estão reconciliados com extrato, conta vinculada e controle de duplicidades.", "Cash receipts are not reconciled to bank evidence, linked accounts and duplicate controls.", "Envie o extrato e o arquivo de baixas que permitam ligar cada recebimento ao título, identificar duplicidades e comprovar a conta de recebimento.", "Provide bank and settlement files that link each receipt to a title, identify duplicates and evidence the collection account.", evidenceIds),
    gap("accounting_reconciliation_not_evidenced", "accounting_reconciliation", "evidence", "Saldo bruto, provisão e recebimentos contábeis ainda não foram ligados à mesma data-base da carteira.", "Gross balance, allowance and accounting collections are not yet tied to the pool reporting date.", "Envie o razão ou balancete da data-base com contas a receber, provisão e baixas para conciliarmos com a carteira.", "Provide the reporting-date ledger or trial balance for receivables, allowance and collections so it can be tied to the pool.", evidenceIds),
    gap("eligibility_policy_not_governed", "eligibility_policy", "policy", "Os critérios e limites da base elegível ainda não foram definidos ou aprovados como premissas do caso.", "Eligibility criteria and limits have not been defined or approved as case assumptions.", "Quais critérios devemos testar para atraso, prazo, concentração, lastro, registro, ônus, diluição, recompra, perdas e cobertura mínima?", "Which criteria should be tested for delinquency, tenor, concentration, evidence, registration, liens, dilution, repurchases, losses and minimum coverage?"),
    gap("facility_and_waterfall_not_governed", "facility_and_waterfall", "structure", "Valor, advance rate, sobrecolateralização, subordinação, reserva e waterfall não estão definidos no contrato do método.", "Facility amount, advance rate, overcollateralization, subordination, reserve and waterfall are not defined in the method contract.", "Qual estrutura devemos simular: valor, advance rate, sobrecolateralização, subordinação, reserva e prioridades do fluxo de caixa?", "Which structure should be simulated: amount, advance rate, overcollateralization, subordination, reserve and cash-flow priorities?"),
  ];
  const incompleteEvents = Object.entries(coverage).filter(([, value]) => value.status !== "complete");
  if (incompleteEvents.length > 0) {
    gaps.push(gap(
      "performance_history_incomplete",
      "performance_history",
      "evidence",
      `O histórico está incompleto para: ${incompleteEvents.map(([name]) => name).join(", ")}. Ausência de evento não será tratada como zero.`,
      `History is incomplete for: ${incompleteEvents.map(([name]) => name).join(", ")}. Missing events will not be treated as zero.`,
      "Envie os históricos completos de liquidação, diluição, prorrogação, recompra, substituição e cessões/ônus para o período analisado.",
      "Provide complete settlement, dilution, extension, repurchase, substitution and assignment/lien histories for the analysis period.",
      evidenceIds,
    ));
  }
  return gaps;
};

const decimalEqual = (left: string, right: string) => new Decimal(left).eq(right);

function assemblyConflicts(
  phaseOne: ReceivablesPhaseOneInput,
  detection: ReceivablesRawDetectionReport,
  assembly: ReceivablesPoolInputAssembly,
): ReceivablesMethodReadinessGap[] {
  const gaps: ReceivablesMethodReadinessGap[] = [];
  const source = phaseOne.universe;
  const method = assembly.input.case;
  const conflict = (code: string, pt: string, en: string) => gaps.push(gap(code, "portfolio_lineage", "conflict", pt, en, "Revise a montagem do input e confirme qual valor e fonte devem prevalecer antes da execução.", "Review the input assembly and confirm which value and source should prevail before execution."));
  if (assembly.source.datasetHash !== phaseOne.datasetHash) conflict("source_dataset_hash_mismatch", "O input montado aponta para outra versão da carteira.", "The assembled input points to a different pool version.");
  if (assembly.source.universeId !== source.id) conflict("source_universe_mismatch", "O input montado aponta para outro universo de recebíveis.", "The assembled input points to a different receivables universe.");
  if (method.referenceDate !== source.dates.reportingDate) conflict("reference_date_mismatch", "A data-base do método diverge da carteira conciliada.", "The method reporting date differs from the reconciled pool.");
  if (assembly.input.currency !== source.currency || method.portfolio.some((item) => assembly.input.currency !== source.currency)) conflict("currency_mismatch", "A moeda do método diverge da carteira conciliada.", "The method currency differs from the reconciled pool.");

  const methodById = new Map(method.portfolio.map((item) => [item.id, item]));
  const sourceById = new Map(source.receivables.map((item) => [item.id, item]));
  const mappedSourceIds = new Set(assembly.source.titleMapping.map((item) => item.sourceReceivableId));
  const mappedMethodIds = new Set(assembly.source.titleMapping.map((item) => item.methodReceivableId));
  if (mappedSourceIds.size !== source.receivables.length || source.receivables.some((item) => !mappedSourceIds.has(item.id))) conflict("source_title_mapping_incomplete", "Nem todos os títulos da carteira de origem foram mapeados.", "Not every source pool title was mapped.");
  if (mappedMethodIds.size !== method.portfolio.length || method.portfolio.some((item) => !mappedMethodIds.has(item.id))) conflict("method_title_mapping_incomplete", "O input do método contém título sem ligação com a carteira de origem.", "The method input contains a title not linked to the source pool.");
  for (const mapping of assembly.source.titleMapping) {
    const sourceTitle = sourceById.get(mapping.sourceReceivableId);
    const methodTitle = methodById.get(mapping.methodReceivableId);
    if (!sourceTitle || !methodTitle) continue;
    if (
      sourceTitle.issueDate !== methodTitle.originDate
      || sourceTitle.currentDueDate !== methodTitle.dueDate
      || sourceTitle.obligorId !== methodTitle.debtorId
      || !decimalEqual(sourceTitle.faceValue, methodTitle.originalAmount)
      || !decimalEqual(sourceTitle.openValue, methodTitle.outstandingBalance)
    ) {
      conflict("mapped_title_economics_mismatch", `O título ${sourceTitle.id} mudou em valor, data ou sacado durante a montagem do input.`, `Title ${sourceTitle.id} changed in amount, date or obligor during input assembly.`);
      break;
    }
  }
  const resolvedFindingIds = new Set(assembly.findingResolutions.map((item) => item.findingId));
  const detectedFindingIds = new Set(detection.defects.map((item) => item.id));
  for (const resolution of assembly.findingResolutions) {
    if (!detectedFindingIds.has(resolution.findingId)) {
      gaps.push(gap(
        `finding_resolution_without_detection:${resolution.findingId}`,
        "title_legal_controls",
        "conflict",
        `Há um tratamento para o achado “${resolution.findingId}”, mas esse achado não pertence à detecção desta carteira.`,
        `A disposition exists for finding “${resolution.findingId}”, but that finding does not belong to this pool detection.`,
        "Confirme se a resolução pertence a outra versão da carteira e remova ou vincule o achado correto.",
        "Confirm whether the resolution belongs to another pool version and remove it or link the correct finding.",
      ));
    }
  }
  for (const finding of detection.defects) {
    if (!resolvedFindingIds.has(finding.id)) {
      gaps.push(gap(
        `finding_unresolved:${finding.id}`,
        "title_legal_controls",
        "conflict",
        `O achado “${finding.description}” ainda não tem tratamento evidenciado no input do método.`,
        `The finding “${finding.description}” has no evidenced treatment in the method input.`,
        "Confirme se o achado foi corrigido, se é falso positivo ou como foi incorporado aos critérios da análise, anexando a evidência.",
        "Confirm whether the finding was remediated, is a false positive or was incorporated into the analysis criteria, with supporting evidence.",
        finding.evidence.flatMap((entry) => entry.kind === "measured" ? entry.anchors.map((anchor) => anchor.kind === "file" ? anchor.fileId : anchor.kind === "document" ? anchor.documentId : anchor.eventId) : []),
      ));
    }
  }
  return gaps;
}

function primaryReason(gaps: readonly ReceivablesMethodReadinessGap[]): ReceivablesPoolMethodReadiness["primaryReason"] {
  if (gaps.some((item) => item.class === "conflict")) return "conflicting";
  if (gaps.some((item) => item.class === "evidence")) return "needs_evidence";
  if (gaps.some((item) => item.class === "policy")) return "needs_policy";
  if (gaps.some((item) => item.class === "structure")) return "needs_structure";
  return "ready";
}

/**
 * Fail-closed bridge between the immutable document rail and specialist execution. It never
 * fills a blank, interprets missing event history as zero or lets a valid-looking method payload
 * execute without a one-to-one source reconciliation and section-level evidence.
 */
export function assessReceivablesPoolMethodReadiness(input: ReadinessInput): ReceivablesPoolMethodReadiness {
  let gaps: ReceivablesMethodReadinessGap[];
  let validatedInput: ReceivablesPoolUnderwritingInput | null = null;
  const parsed = input.assembly === undefined ? null : receivablesPoolInputAssemblySchema.safeParse(input.assembly);
  if (!parsed?.success) {
    gaps = missingAssemblyGaps(input);
    if (parsed && !parsed.success) {
      gaps.unshift(gap("input_assembly_invalid", "portfolio_lineage", "conflict", "A montagem recebida não atende ao contrato governado do método.", "The received assembly does not satisfy the governed method contract.", "Revise os campos inválidos antes de tentar executar a análise especialista.", "Correct the invalid fields before attempting specialist execution."));
    }
  } else {
    gaps = assemblyConflicts(input.phaseOne, input.detection, parsed.data);
    if (gaps.length === 0) validatedInput = parsed.data.input;
  }
  const periodGroups = new Map<string, Set<string>>();
  for (const entry of input.detection.supportPeriodAssessment?.entries ?? []) {
    if (!supportPeriodBlocks(entry)) continue;
    const sources = periodGroups.get(entry.detectorId) ?? new Set<string>();
    sources.add(entry.sourceId);
    periodGroups.set(entry.detectorId, sources);
  }
  const periodGaps = [...periodGroups].sort(([a], [b]) => a.localeCompare(b)).map(([detectorId, sources]) => {
    const reviewOnly = input.detection.supportPeriodAssessment?.entries
      .filter((entry) => entry.detectorId === detectorId && supportPeriodBlocks(entry))
      .every((entry) => entry.requiresSourceReview === true);
    return gap(`support_period:${detectorId}`, detectorId === "cancelled_invoice_open" ? "title_legal_controls" : "accounting_reconciliation", "evidence",
      reviewOnly ? "Data e coluna de saldo dos documentos recebidos ainda precisam ser conferidas." : "O período ou valor da evidência de apoio não está qualificado para a data de corte.",
      reviewOnly ? "The dates and balance columns in the received documents still require review." : "The supporting evidence period or amount is not qualified for the reporting cutoff.",
      reviewOnly ? "Conferir data e coluna de saldo nos documentos recebidos." : "Confirme períodos e valores na fonte e forneça evidência compatível com a data de corte.",
      reviewOnly ? "Review dates and balance columns in the received documents." : "Confirm source periods and amounts and provide evidence compatible with the reporting cutoff.", [...sources]);
  });
  gaps = [...periodGaps, ...gaps];
  if (gaps.length > 0) validatedInput = null;
  const reason = primaryReason(gaps);
  const dimensions = dimensionOrder.map((id) => {
    const dimensionGaps = gaps.filter((item) => item.dimensionId === id);
    return {
      id,
      state: (dimensionGaps.some((item) => item.class === "conflict") ? "conflicting" : dimensionGaps.length > 0 ? "missing" : "satisfied") as "satisfied" | "missing" | "conflicting",
      gapCodes: dimensionGaps.map((item) => item.code).sort(),
    };
  });
  return {
    version: receivablesPoolMethodReadinessVersion,
    state: gaps.length === 0 ? "ready" : "blocked",
    primaryReason: reason,
    methodExecutionAllowed: gaps.length === 0,
    sourceDatasetHash: input.phaseOne.datasetHash,
    dimensions,
    gaps,
    nextQuestions: gaps.map((item) => ({id: item.code, dimensionId: item.dimensionId, text: item.question, evidenceIds: item.evidenceIds})),
    validatedInput,
  };
}

packages/receivables-analysis/src/phase-.content:
import {
  calculateAdjustedDebtBridge,
  calculateDynamicReceivablesMetrics,
  calculateImplicitAdvanceRate,
  calculateSingleMaturityReceivablesProposal,
  calculateStaticReceivablesMetrics,
  type AdjustedDebtBridge,
  type AdjustedDebtBridgeInput,
  type DynamicReceivablesMetrics,
  type GovernedRateAssumption,
  type ImplicitAdvanceRate,
  type IsoDate,
  type ReceivablesUniverse,
  type SingleMaturityReceivablesProposal,
  type SingleMaturityReceivablesProposalInput,
  type StaticReceivablesMetrics,
} from "@offroad/financial-core";

export const receivablesPhaseOneReportVersion = "2026.08.27-v1";

type CanonicalContextFields = "reportingDate" | "universeId" | "datasetHash" | "currency";

export type ReceivablesPhaseOneProposalInput = {
  id: string;
  proposal: Omit<SingleMaturityReceivablesProposalInput, CanonicalContextFields>;
};

export type ReceivablesPhaseOneAdvanceRateInput = {
  periodStart: IsoDate;
  expectedDilution?: GovernedRateAssumption;
  expectedLossRate?: GovernedRateAssumption;
  dilutionStressMultiplier?: GovernedRateAssumption;
  lossStressMultiplier?: GovernedRateAssumption;
  operationalReserve?: GovernedRateAssumption;
  additionalReserves?: readonly GovernedRateAssumption[];
};

export type ReceivablesPhaseOneInput = {
  universe: ReceivablesUniverse;
  datasetHash: string;
  limitations?: readonly string[];
  adjustedDebt?: Omit<AdjustedDebtBridgeInput, CanonicalContextFields>;
  proposals?: readonly ReceivablesPhaseOneProposalInput[];
  advanceRate?: ReceivablesPhaseOneAdvanceRateInput;
};

export type ReceivablesPhaseOneProposalResult = {
  id: string;
  result: SingleMaturityReceivablesProposal;
};

export type ReceivablesPhaseOneReport = {
  version: typeof receivablesPhaseOneReportVersion;
  analysisLayer: "deterministic_math_and_provenance";
  universe: {
    id: string;
    datasetHash: string;
    currency: string;
    reportingDate: IsoDate;
    latestOriginationDate: IsoDate;
    dataStartDate: IsoDate;
    dataEndDate: IsoDate;
  };
  staticMetrics: StaticReceivablesMetrics;
  dynamicMetrics: DynamicReceivablesMetrics;
  adjustedDebt: AdjustedDebtBridge | null;
  proposals: readonly ReceivablesPhaseOneProposalResult[];
  implicitAdvanceRate: ImplicitAdvanceRate | null;
  quality: {
    status: "complete_for_phase_one" | "incomplete";
    blockers: readonly string[];
    warnings: readonly string[];
    limitations: readonly string[];
  };
  boundaries: {
    externalDirectionAllowed: false;
    buyerRecommendationAllowed: false;
    qualifiedIntroductionAllowed: false;
    creditApprovalExpressed: false;
  };
};

function unique(values: readonly string[]): string[] {
  return [...new Set(values.filter((value) => value.length > 0))].sort();
}

export function analyzeReceivablesPhaseOne(input: ReceivablesPhaseOneInput): ReceivablesPhaseOneReport {
  const {universe, datasetHash} = input;
  const staticMetrics = calculateStaticReceivablesMetrics(universe, {datasetHash});
  const dynamicMetrics = calculateDynamicReceivablesMetrics(universe, {datasetHash});
  const adjustedDebt = input.adjustedDebt === undefined
    ? null
    : calculateAdjustedDebtBridge({
      ...input.adjustedDebt,
      reportingDate: universe.dates.reportingDate,
      universeId: universe.id,
      datasetHash,
      currency: universe.currency,
    });

  const proposalIds = new Set<string>();
  const proposals = (input.proposals ?? []).map(({id, proposal}) => {
    if (proposalIds.has(id)) throw new RangeError(`duplicate proposal id: ${id}`);
    proposalIds.add(id);
    return {
      id,
      result: calculateSingleMaturityReceivablesProposal({
        ...proposal,
        reportingDate: universe.dates.reportingDate,
        universeId: universe.id,
        datasetHash,
        currency: universe.currency,
      }),
    };
  });

  const advanceInput = input.advanceRate;
  const implicitAdvanceRate = advanceInput === undefined
    ? null
    : calculateImplicitAdvanceRate({
      reportingDate: universe.dates.reportingDate,
      periodStart: advanceInput.periodStart,
      universeId: universe.id,
      ...(advanceInput.expectedDilution === undefined ? {} : {expectedDilution: advanceInput.expectedDilution}),
      ...(advanceInput.expectedLossRate === undefined ? {} : {expectedLossRate: advanceInput.expectedLossRate}),
      ...(advanceInput.dilutionStressMultiplier === undefined ? {} : {dilutionStressMultiplier: advanceInput.dilutionStressMultiplier}),
      ...(advanceInput.lossStressMultiplier === undefined ? {} : {lossStressMultiplier: advanceInput.lossStressMultiplier}),
      ...(advanceInput.operationalReserve === undefined ? {} : {operationalReserve: advanceInput.operationalReserve}),
      ...(advanceInput.additionalReserves === undefined ? {} : {additionalReserves: advanceInput.additionalReserves}),
    });

  const blockers: string[] = [];
  for (const [event, coverage] of Object.entries(universe.eventCoverage)) {
    if (coverage.status !== "complete") blockers.push(`coverage:${event}:${coverage.status}`);
  }
  if (dynamicMetrics.rollRates.status !== "measured") blockers.push("metric:roll_rates:not_evaluable");
  if (dynamicMetrics.vintages.status !== "measured") blockers.push("metric:vintages:not_evaluable");
  const requiredDynamicMetrics = [
    dynamicMetrics.dilution.shareOfOrigination,
    dynamicMetrics.repurchaseAndLoss.repurchaseShareOfAssigned,
    dynamicMetrics.repurchaseAndLoss.finalWrittenOffShare,
    dynamicMetrics.repurchaseAndLoss.adjustedLossShare,
    dynamicMetrics.punctualSettlement.punctualByCount,
    dynamicMetrics.punctualSettlement.punctualByValue,
    dynamicMetrics.extensions.extendedTitleShare,
    dynamicMetrics.extensions.extendedFaceShare,
    dynamicMetrics.extensions.weightedExtensionDays,
  ];
  for (const metric of requiredDynamicMetrics) {
    if (metric.status !== "measured") blockers.push(`metric:${metric.id}:not_evaluable`);
  }
  if (adjustedDebt === null) blockers.push("adjusted_debt_bridge_not_provided");
  if (proposals.length === 0) blockers.push("financing_proposal_not_provided");
  for (const proposal of proposals) {
    if (proposal.result.cet.status !== "calculated_complete") blockers.push(`proposal:${proposal.id}:complete_cet_not_available`);
  }
  if (implicitAdvanceRate === null) blockers.push("advance_rate_scenario_not_provided");
  else if (implicitAdvanceRate.status !== "calculated") blockers.push("advance_rate_not_evaluable");

  const warnings = unique([
    ...staticMetrics.quality.warnings,
    ...dynamicMetrics.quality.warnings,
    ...(adjustedDebt?.quality.warnings ?? []),
    ...proposals.flatMap((proposal) => proposal.result.cet.quality.warnings.map((warning) => `proposal:${proposal.id}:${warning}`)),
    ...(implicitAdvanceRate?.quality.warnings ?? []),
  ]);
  const coverageLimitations = Object.entries(universe.eventCoverage).flatMap(([event, coverage]) => [
    ...(coverage.status === "complete" ? [] : [`${event}_coverage_${coverage.status}`]),
    ...coverage.limitations.map((limitation) => `${event}:${limitation}`),
  ]);
  const limitations = unique([...(input.limitations ?? []), ...coverageLimitations]);

  return {
    version: receivablesPhaseOneReportVersion,
    analysisLayer: "deterministic_math_and_provenance",
    universe: {
      id: universe.id,
      datasetHash,
      currency: universe.currency,
      reportingDate: universe.dates.reportingDate,
      latestOriginationDate: universe.dates.latestOriginationDate,
      dataStartDate: universe.dates.dataStartDate,
      dataEndDate: universe.dates.dataEndDate,
    },
    staticMetrics,
    dynamicMetrics,
    adjustedDebt,
    proposals,
    implicitAdvanceRate,
    quality: {
      status: blockers.length === 0 ? "complete_for_phase_one" : "incomplete",
      blockers: unique(blockers),
      warnings,
      limitations,
    },
    boundaries: {
      externalDirectionAllowed: false,
      buyerRecommendationAllowed: false,
      qualifiedIntroductionAllowed: false,
      creditApprovalExpressed: false,
    },
  };
}

packages/receivables-analysis/src/method.content:
import {createHash} from "node:crypto";

import type {SourceAnchor} from "@offroad/financial-core";
import Decimal from "decimal.js";
import {z} from "zod";

import {
  eligibilityPolicySchema,
  moneySchema,
  receivablesStructureSchema,
} from "./schema";
import type {ReceivablesPhaseOneInput} from "./phase-one";
import {
  receivablesPoolInputAssemblySchema,
  receivablesPoolInputAssemblyVersion,
  type ReceivablesPoolInputAssembly,
} from "./method-readiness";

export const receivablesPoolInputSupplementVersion = "2026.09.07-v1" as const;

export const receivablesMethodEvidenceReferenceSchema = z.object({
  sourceClass: z.enum(["provided_document", "project_context", "house_method", "user_confirmation"]),
  sourceId: z.string().min(1),
  anchor: z.string().min(1),
}).strict();
export const receivablesMethodEvidenceSectionSchema = z.array(receivablesMethodEvidenceReferenceSchema).min(1);

export const receivablesTitleSupplementSchema = z.object({
  sourceReceivableId: z.string().min(1),
  debtorSector: z.string().min(1),
  collectedInPeriod: moneySchema,
  defaultedBalance: moneySchema,
  recoveredInPeriod: moneySchema,
  dilutionInPeriod: moneySchema,
  repurchasedInPeriod: moneySchema,
  substitutedInPeriod: moneySchema,
  assignable: z.boolean(),
  evidenceVerified: z.boolean(),
  registration: z.enum(["registered", "not_required", "missing", "conflict"]),
  encumbrance: z.enum(["free", "pledged", "assigned", "unknown"]),
  disputed: z.boolean(),
  relatedParty: z.boolean(),
}).strict();

export const receivablesCashSupplementSchema = z.object({
  id: z.string().min(1),
  receivedAt: z.iso.date(),
  amount: moneySchema,
  sourceReceivableId: z.string().min(1).nullable(),
  debtorId: z.string().min(1).nullable(),
  linkedAccount: z.boolean(),
  duplicateOf: z.string().min(1).nullable(),
  sourceDocumentId: z.string().min(1),
  sourceAnchor: z.string().min(1),
  anchorVerified: z.boolean(),
}).strict();

export const receivablesPoolInputSupplementSchema = z.object({
  schemaVersion: z.literal(receivablesPoolInputSupplementVersion),
  sourceDatasetHash: z.string().regex(/^[a-f0-9]{64}$/),
  cedent: z.object({
    id: z.string().min(1),
    legalName: z.string().min(2),
    servicingRole: z.enum(["cedent", "third_party", "shared"]),
  }).strict(),
  titles: z.array(receivablesTitleSupplementSchema).min(1),
  cashReceipts: z.array(receivablesCashSupplementSchema),
  accounting: z.object({
    grossReceivablesBalance: moneySchema,
    allowanceBalance: moneySchema,
    reportedCollectionsInPeriod: moneySchema,
  }).strict(),
  policy: eligibilityPolicySchema,
  structure: receivablesStructureSchema,
  evidence: z.object({
    cedentAndServicing: receivablesMethodEvidenceSectionSchema,
    titleLegalControls: receivablesMethodEvidenceSectionSchema,
    performanceHistory: receivablesMethodEvidenceSectionSchema,
    cashReconciliation: receivablesMethodEvidenceSectionSchema,
    accountingReconciliation: receivablesMethodEvidenceSectionSchema,
    eligibilityPolicy: receivablesMethodEvidenceSectionSchema,
    facilityAndWaterfall: receivablesMethodEvidenceSectionSchema,
  }).strict(),
  findingResolutions: z.array(z.object({
    findingId: z.string().min(1),
    disposition: z.enum(["remediated", "false_positive", "incorporated_in_method_input"]),
    rationale: z.string().min(10),
    evidence: receivablesMethodEvidenceSectionSchema,
  }).strict()),
}).strict().superRefine((supplement, context) => {
  const titleIds = supplement.titles.map((item) => item.sourceReceivableId);
  if (new Set(titleIds).size !== titleIds.length) {
    context.addIssue({code: "custom", path: ["titles"], message: "one supplement per source receivable is required"});
  }
  const receiptIds = supplement.cashReceipts.map((item) => item.id);
  if (new Set(receiptIds).size !== receiptIds.length) {
    context.addIssue({code: "custom", path: ["cashReceipts"], message: "cash receipt ids must be unique"});
  }
  const findingIds = supplement.findingResolutions.map((item) => item.findingId);
  if (new Set(findingIds).size !== findingIds.length) {
    context.addIssue({code: "custom", path: ["findingResolutions"], message: "finding resolutions must be unique"});
  }
});
export type ReceivablesPoolInputSupplement = z.infer<typeof receivablesPoolInputSupplementSchema>;

function methodCaseId(universeId: string): string {
  // Preserve already-valid method IDs; source identifiers may include sheet names,
  // separators and long locators. Hash the complete identifier without truncation.
  return /^[a-z0-9][a-z0-9-]{2,99}$/.test(universeId)
    ? universeId
    : `r01-${createHash("sha256").update(universeId, "utf8").digest("hex")}`;
}

function methodReceivableId(sourceReceivableId: string): string {
  return `r-${createHash("sha256").update(sourceReceivableId).digest("hex").slice(0, 24)}`;
}

function sourceReference(anchor: SourceAnchor): {documentId: string; locator: string} {
  if (anchor.kind === "file") {
    const locators = [anchor.sheet ? `sheet:${anchor.sheet}` : null, anchor.row ? `row:${anchor.row}` : null, anchor.column ? `column:${anchor.column}` : null, anchor.cell ? `cell:${anchor.cell}` : null].filter(Boolean);
    return {documentId: anchor.fileId, locator: locators.join(";") || `file:${anchor.fileId}`};
  }
  if (anchor.kind === "document") {
    const locators = [anchor.page ? `page:${anchor.page}` : null, anchor.clause ? `clause:${anchor.clause}` : null, anchor.paragraph ? `paragraph:${anchor.paragraph}` : null].filter(Boolean);
    return {documentId: anchor.documentId, locator: locators.join(";") || `document:${anchor.documentId}`};
  }
  return {documentId: anchor.sourceSystem, locator: `event:${anchor.eventId};at:${anchor.occurredAt}`};
}

function sumSettlements(input: ReceivablesPhaseOneInput, sourceReceivableId: string): string {
  return input.universe.settlements
    .filter((event) => event.receivableId === sourceReceivableId)
    .reduce((total, event) => total.plus(event.amount), new Decimal(0))
    .toDecimalPlaces(2)
    .toFixed(2);
}

/**
 * Compiles the missing governed facts into the exact specialist method input. Economic title
 * fields and paid-to-date values come only from the immutable Phase 1 universe. The supplement
 * cannot override them; it supplies only the legal, operational, accounting, policy and structure
 * facts that the title tape cannot establish by itself.
 */
export function assembleReceivablesPoolMethodInput(input: {
  phaseOne: ReceivablesPhaseOneInput;
  supplement: unknown;
}): ReceivablesPoolInputAssembly {
  const supplement = receivablesPoolInputSupplementSchema.parse(input.supplement);
  const universe = input.phaseOne.universe;
  if (supplement.sourceDatasetHash !== input.phaseOne.datasetHash) {
    throw new Error("receivables_supplement_dataset_mismatch");
  }
  if (universe.currency !== "BRL" && universe.currency !== "USD") {
    throw new Error("receivables_method_currency_not_supported");
  }
  const supplementByTitle = new Map(supplement.titles.map((item) => [item.sourceReceivableId, item]));
  const sourceIds = new Set(universe.receivables.map((item) => item.id));
  const missing = universe.receivables.filter((item) => !supplementByTitle.has(item.id)).map((item) => item.id).sort();
  const extra = supplement.titles.filter((item) => !sourceIds.has(item.sourceReceivableId)).map((item) => item.sourceReceivableId).sort();
  if (missing.length > 0 || extra.length > 0) {
    throw new Error(`receivables_supplement_title_partition_invalid:missing=${missing.join("|")}:extra=${extra.join("|")}`);
  }
  const methodIdBySource = new Map(universe.receivables.map((item) => [item.id, methodReceivableId(item.id)]));
  const portfolio = universe.receivables.map((title) => {
    const supplied = supplementByTitle.get(title.id)!;
    const source = sourceReference(title.source);
    return {
      id: methodIdBySource.get(title.id)!,
      debtorId: title.obligorId,
      ...(title.economicGroupId ? {debtorGroupId: title.economicGroupId} : {}),
      debtorSector: supplied.debtorSector,
      originDate: title.issueDate,
      dueDate: title.currentDueDate,
      originalAmount: title.faceValue,
      outstandingBalance: title.openValue,
      paidAmount: sumSettlements(input.phaseOne, title.id),
      collectedInPeriod: supplied.collectedInPeriod,
      defaultedBalance: supplied.defaultedBalance,
      recoveredInPeriod: supplied.recoveredInPeriod,
      dilutionInPeriod: supplied.dilutionInPeriod,
      repurchasedInPeriod: supplied.repurchasedInPeriod,
      substitutedInPeriod: supplied.substitutedInPeriod,
      assignable: supplied.assignable,
      evidenceVerified: supplied.evidenceVerified,
      registration: supplied.registration,
      encumbrance: supplied.encumbrance,
      disputed: supplied.disputed,
      relatedParty: supplied.relatedParty,
      sourceDocumentId: source.documentId,
      sourceAnchor: source.locator,
      anchorVerified: true,
    };
  });
  const cashReceipts = supplement.cashReceipts.map(({sourceReceivableId, ...receipt}) => ({
    ...receipt,
    receivableId: sourceReceivableId === null ? null : methodIdBySource.get(sourceReceivableId) ?? null,
  }));
  const unknownCashLinks = supplement.cashReceipts.filter((receipt) => receipt.sourceReceivableId !== null && !methodIdBySource.has(receipt.sourceReceivableId));
  if (unknownCashLinks.length > 0) {
    throw new Error(`receivables_cash_link_not_in_source:${unknownCashLinks.map((item) => item.id).sort().join("|")}`);
  }
  return receivablesPoolInputAssemblySchema.parse({
    schemaVersion: receivablesPoolInputAssemblyVersion,
    source: {
      universeId: universe.id,
      datasetHash: input.phaseOne.datasetHash,
      titleMapping: universe.receivables.map((title) => ({sourceReceivableId: title.id, methodReceivableId: methodIdBySource.get(title.id)!})),
    },
    evidence: supplement.evidence,
    findingResolutions: supplement.findingResolutions,
    input: {
      currency: universe.currency,
      case: {
        schemaVersion: "2026.08.24-v1",
        id: methodCaseId(universe.id),
        referenceDate: universe.dates.reportingDate,
        cedent: supplement.cedent,
        portfolio,
        cashReceipts,
        accounting: supplement.accounting,
        policy: supplement.policy,
        structure: supplement.structure,
      },
    },
  });
}

packages/financial-core/src/index.ts.content:
import Decimal from "decimal.js";

export const financialCoreVersion = "2026.09.10-v16";

export * from "./financial-truth";
export * from "./depreciation";
export * from "./assumption-unit";
export * from "./indexed-debt";
export * from "./operation";
export * from "./receivables/contracts";
export * from "./receivables/eligibility-allocation";
export {receivablesPoolKernelsVersion, type ReceivablesPoolKernelTrace} from "./receivables/pool-shared";
export * from "./receivables/pool-eligibility";
export * from "./receivables/pool-concentration";
export * from "./receivables/pool-waterfall";
export * from "./receivables/pool-borrowing-base";
export * from "./receivables/pool-reconciliation";
export * from "./receivables/pool-performance";
export * from "./receivables/pool-triggers";
export * from "./receivables/provider-allocation";
export * from "./receivables/dynamic-metrics";
export * from "./receivables/static-metrics";
export * from "./receivables/structure-cost";
export * from "./structure";

Decimal.set({precision: 40, rounding: Decimal.ROUND_HALF_UP, toExpNeg: -30, toExpPos: 30});

export type DecimalInput = Decimal.Value;

export type CalculationResult = {
  value: string;
  trace: Array<{label: string; value: string}>;
  warnings: string[];
};

const d = (value: DecimalInput) => new Decimal(value);
const canonical = (value: Decimal) => value.toDecimalPlaces(8).toFixed();

function result(value: Decimal, trace: CalculationResult["trace"], warnings: string[] = []): CalculationResult {
  return {value: canonical(value), trace, warnings};
}

export function calculateAdjustedEbitda(reportedEbitda: DecimalInput, adjustments: DecimalInput[]): CalculationResult {
  const base = d(reportedEbitda);
  const adjustmentTotal = adjustments.reduce<Decimal>((sum, item) => sum.plus(item), new Decimal(0));
  return result(base.plus(adjustmentTotal), [
    {label: "reported_ebitda", value: canonical(base)},
    {label: "approved_adjustments", value: canonical(adjustmentTotal)},
  ]);
}

export function calculateLeverage(netDebt: DecimalInput, adjustedEbitda: DecimalInput): CalculationResult {
  const debt = d(netDebt);
  const ebitda = d(adjustedEbitda);
  if (ebitda.lte(0)) {
    throw new RangeError("adjusted EBITDA must be positive");
  }
  return result(debt.div(ebitda), [
    {label: "net_debt", value: canonical(debt)},
    {label: "adjusted_ebitda", value: canonical(ebitda)},
  ]);
}

/**
 * Brazilian business-day accrual: the factor an annual effective rate accumulates over `businessDays`
 * of a 252-day year, as indentures state it ((1 + rate)^(DU/252) - 1). Rates are decimals.
 */
export function businessDayAccrual(annualRate: DecimalInput, businessDays: number): CalculationResult {
  if (!Number.isInteger(businessDays) || businessDays < 0) throw new RangeError("business days must be a non-negative integer");
  const rate = d(annualRate);
  if (rate.lte(-1)) throw new RangeError("an annual rate below -100% has no accrual factor");
  const factor = rate.plus(1).pow(new Decimal(businessDays).div(252)).minus(1);
  return result(factor, [
    {label: "annual_rate", value: canonical(rate)},
    {label: "business_days", value: String(businessDays)},
  ]);
}

/**
 * The DI factor of a "p% of DI" remuneration over `businessDays`, with a flat annual DI: each day accrues
 * p times the daily DI rate and the days compound ((1 + ((1 + DI)^(1/252) - 1) * p)^DU - 1).
 */
export function diPercentAccrual(annualDi: DecimalInput, percentOfDi: DecimalInput, businessDays: number): CalculationResult {
  if (!Number.isInteger(businessDays) || businessDays < 0) throw new RangeError("business days must be a non-negative integer");
  const di = d(annualDi);
  const percent = d(percentOfDi);
  if (di.lte(-1) || percent.lt(0)) throw new RangeError("the DI must be above -100% and the percentage non-negative");
  const daily = di.plus(1).pow(new Decimal(1).div(252)).minus(1).times(percent);
  const factor = daily.plus(1).pow(businessDays).minus(1);
  return result(factor, [
    {label: "annual_di", value: canonical(di)},
    {label: "percent_of_di", value: canonical(percent)},
    {label: "business_days", value: String(businessDays)},
  ]);
}

/** The EBITDA a reported leverage implies for a given net debt: netDebt / index. The caller marks it derived, never a fact. */
export function calculateImpliedEbitda(netDebt: DecimalInput, reportedIndex: DecimalInput): CalculationResult {
  const debt = d(netDebt);
  const index = d(reportedIndex);
  if (index.lte(0)) {
    throw new RangeError("a reported index must be positive to imply an EBITDA");
  }
  return result(debt.div(index), [
    {label: "net_debt", value: canonical(debt)},
    {label: "reported_index", value: canonical(index)},
  ]);
}

export function calculateDscr(cfads: DecimalInput, debtService: DecimalInput): CalculationResult {
  const cash = d(cfads);
  const service = d(debtService);
  if (service.lte(0)) {
    throw new RangeError("debt service must be positive");
  }
  return result(cash.div(service), [
    {label: "cfads", value: canonical(cash)},
    {label: "debt_service", value: canonical(service)},
  ]);
}

export function applyCollateralHaircuts(
  items: Array<{name: string; grossValue: DecimalInput; haircutRate: DecimalInput}>,
): CalculationResult {
  const trace: CalculationResult["trace"] = [];
  const value = items.reduce((total, item) => {
    const gross = d(item.grossValue);
    const haircut = d(item.haircutRate);
    if (haircut.lt(0) || haircut.gt(1)) {
      throw new RangeError("haircut rate must be between zero and one");
    }
    const eligible = gross.mul(new Decimal(1).minus(haircut));
    trace.push({label: item.name, value: canonical(eligible)});
    return total.plus(eligible);
  }, new Decimal(0));
  return result(value, trace);
}

export function solveMaximumDebtByDscr(
  cfads: DecimalInput,
  minimumDscr: DecimalInput,
  annualDebtServiceFactor: DecimalInput,
): CalculationResult {
  const cash = d(cfads);
  const dscr = d(minimumDscr);
  const factor = d(annualDebtServiceFactor);
  if (dscr.lte(0) || factor.lte(0)) {
    throw new RangeError("minimum DSCR and debt service factor must be positive");
  }
  return result(cash.div(dscr).div(factor), [
    {label: "cfads", value: canonical(cash)},
    {label: "minimum_dscr", value: canonical(dscr)},
