import Decimal from "decimal.js";

import {decimal, full, receivablesPoolKernelsVersion, requireNonNegative, requireUnitInterval, sum, ZERO, type ReceivablesPoolKernelTrace} from "./pool-shared";

export type ReceivablesPoolConcentrationItem = {
  debtorId: string;
  /** Economic group of the debtor; a debtor outside any group is its own group. */
  debtorGroupId: string;
  balance: string;
};

export type ReceivablesPoolConcentrationCap = {
  version: typeof receivablesPoolKernelsVersion;
  /** The caps are shares of the preliminary eligible balance, never of the final adjusted base. */
  denominator: "preliminary_eligible_balance";
  order: readonly ["debtor", "economic_group"];
  preliminaryEligibleBalance: string;
  debtorCap: string;
  groupCap: string;
  adjustedEligibleBalance: string;
  excessRemoved: string;
  groups: Array<{
    groupId: string;
    balance: string;
    afterDebtorCaps: string;
    afterGroupCap: string;
    debtors: Array<{debtorId: string; balance: string; retained: string}>;
  }>;
  trace: ReceivablesPoolKernelTrace;
};

/**
 * Applies the declared single-debtor and economic-group caps to the preliminary eligible balance.
 * Both caps are shares of that preliminary balance (the denominator convention the result must
 * state). Each debtor is capped first, then each group's capped sum is capped again; an excess
 * removed at the debtor level is never removed a second time at the group level. This is not an
 * iterative solver for limits defined over the final base after exclusions.
 */
export function capReceivablesPoolConcentration(input: {
  items: readonly ReceivablesPoolConcentrationItem[];
  maxSingleDebtorShare: string;
  maxDebtorGroupShare: string;
}): ReceivablesPoolConcentrationCap {
  const maxDebtorShare = requireUnitInterval("maxSingleDebtorShare", input.maxSingleDebtorShare);
  const maxGroupShare = requireUnitInterval("maxDebtorGroupShare", input.maxDebtorGroupShare);
  const groupOfDebtor = new Map<string, string>();
  for (const item of input.items) {
    requireNonNegative(`balance of ${item.debtorId}`, item.balance);
    const known = groupOfDebtor.get(item.debtorId);
    if (known !== undefined && known !== item.debtorGroupId) throw new RangeError(`debtor ${item.debtorId} cannot belong to two economic groups`);
    groupOfDebtor.set(item.debtorId, item.debtorGroupId);
  }
  const preliminary = sum(input.items.map((item) => item.balance));
  const debtorCap = preliminary.times(maxDebtorShare);
  const groupCap = preliminary.times(maxGroupShare);
  const groups = new Map<string, Map<string, Decimal>>();
  for (const item of input.items) {
    const debtors = groups.get(item.debtorGroupId) ?? new Map<string, Decimal>();
    debtors.set(item.debtorId, (debtors.get(item.debtorId) ?? ZERO).plus(item.balance));
    groups.set(item.debtorGroupId, debtors);
  }
  let adjusted = ZERO;
  const groupResults: ReceivablesPoolConcentrationCap["groups"] = [];
  for (const [groupId, debtors] of groups) {
    let afterDebtorCaps = ZERO;
    const debtorResults: ReceivablesPoolConcentrationCap["groups"][number]["debtors"] = [];
    for (const [debtorId, balance] of debtors) {
      const retained = Decimal.min(balance, debtorCap);
      afterDebtorCaps = afterDebtorCaps.plus(retained);
      debtorResults.push({debtorId, balance: full(balance), retained: full(retained)});
    }
    const afterGroupCap = Decimal.min(afterDebtorCaps, groupCap);
    adjusted = adjusted.plus(afterGroupCap);
    groupResults.push({
      groupId,
      balance: full(sum(debtors.values())),
      afterDebtorCaps: full(afterDebtorCaps),
      afterGroupCap: full(afterGroupCap),
      debtors: debtorResults,
    });
  }
  return {
    version: receivablesPoolKernelsVersion,
    denominator: "preliminary_eligible_balance",
    order: ["debtor", "economic_group"],
    preliminaryEligibleBalance: full(preliminary),
    debtorCap: full(debtorCap),
    groupCap: full(groupCap),
    adjustedEligibleBalance: full(adjusted),
    excessRemoved: full(preliminary.minus(adjusted)),
    groups: groupResults,
    trace: {
      id: "receivables.pool_concentration_cap",
      formula: "debtorCap = preliminary * maxSingleDebtorShare; groupCap = preliminary * maxDebtorGroupShare; adjusted = sum over groups of min(sum over debtors of min(debtorBalance, debtorCap), groupCap)",
      operands: {
        preliminaryEligibleBalance: full(preliminary),
        maxSingleDebtorShare: full(decimal(maxDebtorShare)),
        maxDebtorGroupShare: full(decimal(maxGroupShare)),
        debtorCap: full(debtorCap),
        groupCap: full(groupCap),
        groups: String(groups.size),
      },
      result: full(adjusted),
    },
  };
}

import Decimal from "decimal.js";

import type {AssertionProvenance, ReceivablesUniverse} from "./contracts";

export const receivablesEligibilityAllocationVersion = "2026.08.27-v1";

export type ReceivableEligibilityDisposition = "eligible" | "conditional" | "ineligible" | "not_evaluated";

export type ReceivableEligibilityClassification = {
  receivableId: string;
  disposition: ReceivableEligibilityDisposition;
  reason: string;
  provenance: AssertionProvenance;
};

export type ReceivablesEligibilityAllocation = {
  version: typeof receivablesEligibilityAllocationVersion;
  denominator: "open_receivables_value";
  denominatorValue: string;
  amounts: Record<ReceivableEligibilityDisposition, string>;
  shares: Record<ReceivableEligibilityDisposition, string | null>;
  titleCounts: Record<ReceivableEligibilityDisposition, number>;
  classifications: readonly ReceivableEligibilityClassification[];
  provenance: {
    datasetHash: string;
    universeId: string;
    reportingDate: string;
    inclusions: readonly string[];
    exclusions: readonly string[];
  };
};

const dispositions: readonly ReceivableEligibilityDisposition[] = ["eligible", "conditional", "ineligible", "not_evaluated"];
const canonical = (value: Decimal) => value.toDecimalPlaces(8).toFixed();

/**
 * Aggregates externally classified title-level decisions. Legal and policy logic deliberately
 * stays outside financial-core; this function only enforces a complete, exclusive denominator.
 */
export function calculateReceivablesEligibilityAllocation(input: {
  universe: ReceivablesUniverse;
  datasetHash: string;
  classifications: readonly ReceivableEligibilityClassification[];
}): ReceivablesEligibilityAllocation {
  const openTitles = input.universe.receivables.filter((title) => title.status === "open");
  const openIds = new Set(openTitles.map((title) => title.id));
  const byId = new Map<string, ReceivableEligibilityClassification>();
  for (const classification of input.classifications) {
    if (!openIds.has(classification.receivableId)) throw new RangeError(`classification is not for an open receivable: ${classification.receivableId}`);
    if (byId.has(classification.receivableId)) throw new RangeError(`duplicate eligibility classification: ${classification.receivableId}`);
    if (classification.provenance.kind === "estimated" && classification.disposition === "ineligible") {
      throw new Error(`estimated provenance cannot create a hard ineligibility: ${classification.receivableId}`);
    }
    byId.set(classification.receivableId, classification);
  }
  const missing = openTitles.filter((title) => !byId.has(title.id)).map((title) => title.id).sort();
  if (missing.length > 0) throw new RangeError(`missing eligibility classifications: ${missing.join(",")}`);

  const amounts = Object.fromEntries(dispositions.map((item) => [item, new Decimal(0)])) as Record<ReceivableEligibilityDisposition, Decimal>;
  const titleCounts = Object.fromEntries(dispositions.map((item) => [item, 0])) as Record<ReceivableEligibilityDisposition, number>;
  for (const title of openTitles) {
    const classification = byId.get(title.id)!;
    amounts[classification.disposition] = amounts[classification.disposition].plus(title.openValue);
    titleCounts[classification.disposition] += 1;
  }
  const denominator = openTitles.reduce((sum, title) => sum.plus(title.openValue), new Decimal(0));
  const serializedAmounts = Object.fromEntries(dispositions.map((item) => [item, canonical(amounts[item])])) as Record<ReceivableEligibilityDisposition, string>;
  const shares = Object.fromEntries(dispositions.map((item) => [item, denominator.eq(0) ? null : canonical(amounts[item].div(denominator))])) as Record<ReceivableEligibilityDisposition, string | null>;

  const allocated = dispositions.reduce((sum, item) => sum.plus(amounts[item]), new Decimal(0));
  if (!allocated.eq(denominator)) throw new Error("eligibility allocation does not reconcile to the open portfolio");

  return {
    version: receivablesEligibilityAllocationVersion,
    denominator: "open_receivables_value",
    denominatorValue: canonical(denominator),
    amounts: serializedAmounts,
    shares,
    titleCounts,
    classifications: openTitles.map((title) => byId.get(title.id)!),
    provenance: {
      datasetHash: input.datasetHash,
      universeId: input.universe.id,
      reportingDate: input.universe.dates.reportingDate,
      inclusions: ["open receivables present in the canonical universe"],
      exclusions: ["settled, cancelled, repurchased and written-off receivables"],
    },
  };
}

import Decimal from "decimal.js";

import {full, receivablesPoolKernelsVersion, requireNonNegative, ZERO, type ReceivablesPoolKernelTrace} from "./pool-shared";

/** The fixed priority order of the indicative waterfall. The input carries amounts, never a free list of priorities. */
export const receivablesPoolWaterfallOrder = [
  "servicing_fee", "senior_interest", "reserve_top_up", "senior_principal", "mezzanine", "subordinated_residual",
] as const;
export type ReceivablesPoolWaterfallItem = typeof receivablesPoolWaterfallOrder[number];

export type ReceivablesPoolWaterfallAllocation = {
  priority: number;
  item: ReceivablesPoolWaterfallItem;
  due: string;
  paid: string;
  shortfall: string;
};

export type ReceivablesPoolWaterfall = {
  version: typeof receivablesPoolKernelsVersion;
  order: typeof receivablesPoolWaterfallOrder;
  availableCash: string;
  reserveTarget: string;
  reserveTopUpDue: string;
  allocations: ReceivablesPoolWaterfallAllocation[];
  /** Cash left after the five obligations: it goes to the subordinated tranche as residual. */
  subordinatedResidual: string;
  /** Cash left after the residual is allocated: always zero, the waterfall never creates or strands cash. */
  unallocatedCash: string;
  totalPaid: string;
  seniorShortfall: string;
  trace: ReceivablesPoolKernelTrace;
};

/**
 * Allocates available cash in the fixed order servicing fee, senior interest, reserve top-up,
 * senior principal, mezzanine and subordinated residual. Every level receives the lesser of the
 * remaining cash and its obligation, so cash never goes negative and the paid amounts sum to the
 * cash available. The reserve top-up is the target less the opening balance, floored at zero.
 */
export function allocateReceivablesPoolWaterfall(input: {
  availableCash: string;
  servicingFeeDue: string;
  seniorInterestDue: string;
  seniorPrincipalDue: string;
  mezzanineDue: string;
  reserveOpening: string;
  reserveTarget: string;
}): ReceivablesPoolWaterfall {
  let cash = requireNonNegative("availableCash", input.availableCash);
  const availableCash = cash;
  const reserveTarget = requireNonNegative("reserveTarget", input.reserveTarget);
  const reserveOpening = requireNonNegative("reserveOpening", input.reserveOpening);
  const reserveTopUp = Decimal.max(reserveTarget.minus(reserveOpening), ZERO);
  const dueItems: Array<{item: ReceivablesPoolWaterfallItem; due: Decimal}> = [
    {item: "servicing_fee", due: requireNonNegative("servicingFeeDue", input.servicingFeeDue)},
    {item: "senior_interest", due: requireNonNegative("seniorInterestDue", input.seniorInterestDue)},
    {item: "reserve_top_up", due: reserveTopUp},
    {item: "senior_principal", due: requireNonNegative("seniorPrincipalDue", input.seniorPrincipalDue)},
    {item: "mezzanine", due: requireNonNegative("mezzanineDue", input.mezzanineDue)},
  ];
  let totalPaid = ZERO;
  let seniorShortfall = ZERO;
  const allocations: ReceivablesPoolWaterfallAllocation[] = dueItems.map(({item, due}, index) => {
    const paid = Decimal.min(cash, due);
    cash = cash.minus(paid);
    totalPaid = totalPaid.plus(paid);
    const shortfall = due.minus(paid);
    if (item === "senior_interest" || item === "senior_principal") seniorShortfall = seniorShortfall.plus(shortfall);
    return {priority: index + 1, item, due: full(due), paid: full(paid), shortfall: full(shortfall)};
  });
  const residual = cash;
  totalPaid = totalPaid.plus(residual);
  allocations.push({priority: 6, item: "subordinated_residual", due: full(residual), paid: full(residual), shortfall: full(ZERO)});
  return {
    version: receivablesPoolKernelsVersion,
    order: receivablesPoolWaterfallOrder,
    availableCash: full(availableCash),
    reserveTarget: full(reserveTarget),
    reserveTopUpDue: full(reserveTopUp),
    allocations,
    subordinatedResidual: full(residual),
    unallocatedCash: full(ZERO),
    totalPaid: full(totalPaid),
    seniorShortfall: full(seniorShortfall),
    trace: {
      id: "receivables.pool_waterfall",
      formula: "for each level in fixed order: paid = min(remainingCash, due); remainingCash -= paid; reserveTopUp = max(reserveTarget - reserveOpening, 0); residual = remainingCash after mezzanine",
      operands: {
        availableCash: full(availableCash),
        servicingFeeDue: allocations[0]!.due,
        seniorInterestDue: allocations[1]!.due,
        reserveTarget: full(reserveTarget),
        reserveOpening: full(reserveOpening),
        reserveTopUpDue: full(reserveTopUp),
        seniorPrincipalDue: allocations[3]!.due,
        mezzanineDue: allocations[4]!.due,
      },
      result: full(totalPaid),
    },
  };
}

import Decimal from "decimal.js";

import {decimal, full, ONE, receivablesPoolKernelsVersion, requireNonNegative, requireUnitInterval, safeRatio, sum, type ReceivablesPoolKernelTrace} from "./pool-shared";

export type ReceivablesPoolCashReceipt = {
  id: string;
  amount: string;
  receivableId: string | null;
  debtorId: string | null;
  linkedAccount: boolean;
  duplicateOf: string | null;
  anchorVerified: boolean;
};

export type ReceivablesPoolReconciliationLine = {
  left: string;
  right: string;
  difference: string;
  /** Absolute difference over the larger of |right| and one, so a zero ledger cannot divide by zero. */
  differenceShare: string;
  tolerance: string;
  status: "tied" | "outside_tolerance";
};

export type ReceivablesPoolReconciliation = {
  version: typeof receivablesPoolKernelsVersion;
  /** Title balances of the tape against the accounting gross receivables balance. */
  tapeToAccounting: ReceivablesPoolReconciliationLine;
  /** Collections recorded on the titles against the collections the accounting reports. */
  tapeCollectionsToAccounting: ReceivablesPoolReconciliationLine;
  /** Reported collections against the cash actually received, duplicates excluded. */
  collectionsToCash: ReceivablesPoolReconciliationLine;
  cashControls: {
    grossCashReceipts: string;
    validCashReceipts: string;
    mappedCash: string;
    linkedAccountCash: string;
    /** Mapped cash over valid cash (floored at one); the caller decides how a zero-cash period counts. */
    mappedShare: string;
    linkedAccountShare: string;
    duplicateReceiptIds: string[];
    unanchoredReceiptIds: string[];
    unknownMappingReceiptIds: string[];
    excludedDuplicateCash: string;
  };
  trace: ReceivablesPoolKernelTrace;
};

/**
 * Ties the tape to the accounting control, the tape collections to the reported collections and
 * the reported collections to cash, keeping every difference above tolerance visible. Receipts
 * named as duplicates are excluded from cash before any comparison; a receipt whose title is
 * unknown or whose debtor differs from the tape is an unknown mapping and never counts as mapped.
 */
export function reconcileReceivablesPoolLedgers(input: {
  tapeOutstanding: string;
  accountingGrossBalance: string;
  tapeCollections: string;
  reportedCollections: string;
  receipts: readonly ReceivablesPoolCashReceipt[];
  titles: readonly {id: string; debtorId: string}[];
  maximumAccountingMismatchShare: string;
  maximumCashMismatchShare: string;
}): ReceivablesPoolReconciliation {
  const tape = requireNonNegative("tapeOutstanding", input.tapeOutstanding);
  const accounting = requireNonNegative("accountingGrossBalance", input.accountingGrossBalance);
  const tapeCollections = requireNonNegative("tapeCollections", input.tapeCollections);
  const reportedCollections = requireNonNegative("reportedCollections", input.reportedCollections);
  const accountingTolerance = requireUnitInterval("maximumAccountingMismatchShare", input.maximumAccountingMismatchShare);
  const cashTolerance = requireUnitInterval("maximumCashMismatchShare", input.maximumCashMismatchShare);
  for (const receipt of input.receipts) requireNonNegative(`amount of receipt ${receipt.id}`, receipt.amount);

  const validReceipts = input.receipts.filter((receipt) => receipt.duplicateOf === null);
  const cash = sum(validReceipts.map((receipt) => receipt.amount));
  const grossCash = sum(input.receipts.map((receipt) => receipt.amount));
  const titleById = new Map(input.titles.map((title) => [title.id, title]));
  const unknownMappingReceiptIds = validReceipts.filter((receipt) => {
    if (receipt.receivableId === null || receipt.debtorId === null) return false;
    const title = titleById.get(receipt.receivableId);
    return title === undefined || title.debtorId !== receipt.debtorId;
  }).map((receipt) => receipt.id);
  const unknownMapping = new Set(unknownMappingReceiptIds);
  const mappedCash = sum(validReceipts.filter((receipt) => receipt.receivableId !== null && receipt.debtorId !== null && !unknownMapping.has(receipt.id)).map((receipt) => receipt.amount));
  const linkedCash = sum(validReceipts.filter((receipt) => receipt.linkedAccount).map((receipt) => receipt.amount));

  const line = (left: Decimal, right: Decimal, tolerance: Decimal): ReceivablesPoolReconciliationLine => {
    const difference = left.minus(right).abs();
    const differenceShare = safeRatio(difference, Decimal.max(right.abs(), ONE));
    return {
      left: full(left), right: full(right), difference: full(difference), differenceShare: full(differenceShare),
      tolerance: full(tolerance), status: differenceShare.lte(tolerance) ? "tied" : "outside_tolerance",
    };
  };
  const tapeToAccounting = line(tape, accounting, accountingTolerance);
  const tapeCollectionsToAccounting = line(tapeCollections, reportedCollections, cashTolerance);
  const collectionsToCash = line(cash, reportedCollections, cashTolerance);
  return {
    version: receivablesPoolKernelsVersion,
    tapeToAccounting,
    tapeCollectionsToAccounting,
    collectionsToCash,
    cashControls: {
      grossCashReceipts: full(grossCash),
      validCashReceipts: full(cash),
      mappedCash: full(mappedCash),
      linkedAccountCash: full(linkedCash),
      mappedShare: full(safeRatio(mappedCash, Decimal.max(cash, ONE))),
      linkedAccountShare: full(safeRatio(linkedCash, Decimal.max(cash, ONE))),
      duplicateReceiptIds: input.receipts.filter((receipt) => receipt.duplicateOf !== null).map((receipt) => receipt.id),
      unanchoredReceiptIds: input.receipts.filter((receipt) => !receipt.anchorVerified).map((receipt) => receipt.id),
      unknownMappingReceiptIds,
      excludedDuplicateCash: full(grossCash.minus(cash)),
    },
    trace: {
      id: "receivables.pool_reconciliation",
      formula: "difference = |left - right|; differenceShare = difference / max(|right|, 1); tied when differenceShare <= tolerance; cash excludes receipts named as duplicates; mappedShare = mappedCash / max(cash, 1)",
      operands: {
        tapeOutstanding: full(tape),
        accountingGrossBalance: full(accounting),
        tapeCollections: full(tapeCollections),
        reportedCollections: full(reportedCollections),
        validCashReceipts: full(cash),
        grossCashReceipts: full(grossCash),
        receipts: String(input.receipts.length),
        maximumAccountingMismatchShare: full(decimal(accountingTolerance)),
        maximumCashMismatchShare: full(decimal(cashTolerance)),
      },
      result: [tapeToAccounting.status, tapeCollectionsToAccounting.status, collectionsToCash.status].join(","),
    },
  };
}

import Decimal from "decimal.js";

/**
 * Shared conventions of the receivables-pool kernels (eligibility, concentration, waterfall,
 * borrowing base, reconciliation, performance, evidence coverage and triggers).
 *
 * Every kernel returns its figures as full-precision decimal strings (`Decimal#toFixed()` with
 * no rounding) and a trace naming the formula and operands. Presentation rounding (two decimals
 * for money, eight for ratios) belongs to the caller that publishes the result, so a method can
 * change how it prints without changing what it computed.
 */
export const receivablesPoolKernelsVersion = "2026.09.10-v1";

// The same arithmetic contract the package root declares, so a kernel imported on its own computes
// exactly what it computes inside the published result.
Decimal.set({precision: 40, rounding: Decimal.ROUND_HALF_UP, toExpNeg: -30, toExpPos: 30});

export type ReceivablesPoolKernelTrace = {
  id: string;
  formula: string;
  operands: Record<string, string>;
  result: string;
};

export const ZERO = new Decimal(0);
export const ONE = new Decimal(1);

export const decimal = (value: Decimal.Value): Decimal => new Decimal(value);

/** Full-precision fixed-point string: what the kernel computed, without presentation rounding. */
export const full = (value: Decimal): string => value.toFixed();

export function sum(values: Iterable<Decimal.Value>): Decimal {
  let total = ZERO;
  for (const value of values) total = total.plus(value);
  return total;
}

/** A share whose denominator may legitimately be zero: an empty universe has a zero share, never an error. */
export function safeRatio(numerator: Decimal, denominator: Decimal): Decimal {
  return denominator.isZero() ? ZERO : numerator.div(denominator);
}

export function requireNonNegative(label: string, value: Decimal.Value): Decimal {
  const parsed = decimal(value);
  if (!parsed.isFinite() || parsed.isNegative()) throw new RangeError(`${label} must be a non-negative finite number`);
  return parsed;
}

export function requireUnitInterval(label: string, value: Decimal.Value): Decimal {
  const parsed = requireNonNegative(label, value);
  if (parsed.gt(ONE)) throw new RangeError(`${label} must be between zero and one`);
  return parsed;
}

import Decimal from "decimal.js";

export const receivablesProviderAllocationFormula = {
  id: "receivables_provider_allocation_envelope",
  version: "2026.08.27-v1",
} as const;

export type ReceivablesProviderAllocationInput = {
  requestedAmount: string;
  ticketMinimum: string;
  ticketMaximum: string;
  availableCapacity: string;
  eligiblePortfolioAmount: string;
  conditionalPortfolioAmount: string;
};

export type ReceivablesProviderAllocationEnvelope = {
  formula: typeof receivablesProviderAllocationFormula;
  maximumConfirmedAllocation: string;
  maximumAllocationIncludingConditional: string;
  minimumTicketMet: boolean;
  minimumTicketMetIncludingConditional: boolean;
  wholeRequestCovered: boolean;
};

function nonNegative(value: string, label: string): Decimal {
  const parsed = new Decimal(value);
  if (!parsed.isFinite() || parsed.isNegative()) throw new RangeError(`${label} must be a non-negative decimal`);
  return parsed;
}

function minimum(values: readonly Decimal[]): Decimal {
  return values.reduce((result, value) => Decimal.min(result, value));
}

export function calculateReceivablesProviderAllocation(
  input: ReceivablesProviderAllocationInput,
): ReceivablesProviderAllocationEnvelope {
  const requested = nonNegative(input.requestedAmount, "requestedAmount");
  const ticketMinimum = nonNegative(input.ticketMinimum, "ticketMinimum");
  const ticketMaximum = nonNegative(input.ticketMaximum, "ticketMaximum");
  const availableCapacity = nonNegative(input.availableCapacity, "availableCapacity");
  const eligible = nonNegative(input.eligiblePortfolioAmount, "eligiblePortfolioAmount");
  const conditional = nonNegative(input.conditionalPortfolioAmount, "conditionalPortfolioAmount");
  if (ticketMaximum.lt(ticketMinimum)) throw new RangeError("ticketMaximum must be greater than or equal to ticketMinimum");
  const maximumConfirmed = minimum([requested, ticketMaximum, availableCapacity, eligible]);
  const maximumIncludingConditional = minimum([requested, ticketMaximum, availableCapacity, eligible.plus(conditional)]);
  return {
    formula: receivablesProviderAllocationFormula,
    maximumConfirmedAllocation: maximumConfirmed.toFixed(2),
    maximumAllocationIncludingConditional: maximumIncludingConditional.toFixed(2),
    minimumTicketMet: maximumConfirmed.gte(ticketMinimum),
    minimumTicketMetIncludingConditional: maximumIncludingConditional.gte(ticketMinimum),
    wholeRequestCovered: maximumConfirmed.gte(requested),
  };
}

import Decimal from "decimal.js";

import type {ReceivablesAgingBucket} from "./contracts";
import {full, receivablesPoolKernelsVersion, requireNonNegative, safeRatio, sum, ZERO, type ReceivablesPoolKernelTrace} from "./pool-shared";

export type ReceivablesPoolPerformanceTitle = {
  originalAmount: string;
  defaultedBalance: string;
  recoveredInPeriod: string;
  dilutionInPeriod: string;
  repurchasedInPeriod: string;
  substitutedInPeriod: string;
};

/** The five past-due groupings the pool result publishes, folded from the seven canonical aging buckets. */
export type ReceivablesPoolAgingGroup = "current" | "days_1_30" | "days_31_60" | "days_61_90" | "days_91_plus";

export type ReceivablesPoolPerformance = {
  version: typeof receivablesPoolKernelsVersion;
  /** Ratios derived from the aggregates each title reports; they are not measured longitudinal history. */
  basis: "reported_title_aggregates";
  aging: Record<ReceivablesPoolAgingGroup, string>;
  amounts: {
    totalOutstanding: string;
    overdue1Plus: string;
    overdue30Plus: string;
    overdue90Plus: string;
    originated: string;
    defaulted: string;
    recovered: string;
    netLoss: string;
    dilution: string;
    repurchase: string;
    substitution: string;
  };
  ratios: {
    delinquency1Share: string;
    delinquency30Share: string;
    delinquency90Share: string;
    grossDefaultRate: string;
    netLossRate: string;
    recoveryRate: string;
    dilutionRate: string;
    repurchaseRate: string;
    substitutionRate: string;
  };
  trace: ReceivablesPoolKernelTrace;
};

/**
 * Folds the canonical aging buckets into the published groups and derives the reported-aggregate
 * performance ratios: delinquency over the outstanding balance, default, loss, dilution,
 * repurchase and substitution over the originated amount, recovery over the defaulted balance.
 * A zero denominator yields a zero ratio; the caller states when that means "not evaluable".
 */
export function calculateReceivablesPoolPerformance(input: {
  totalOutstanding: string;
  agingBuckets: Record<ReceivablesAgingBucket, string>;
  titles: readonly ReceivablesPoolPerformanceTitle[];
}): ReceivablesPoolPerformance {
  const total = requireNonNegative("totalOutstanding", input.totalOutstanding);
  const bucket = (name: ReceivablesAgingBucket) => requireNonNegative(`aging bucket ${name}`, input.agingBuckets[name]);
  const aging = {
    current: bucket("not_due"),
    days_1_30: bucket("past_due_1_15").plus(bucket("past_due_16_30")),
    days_31_60: bucket("past_due_31_60"),
    days_61_90: bucket("past_due_61_90"),
    days_91_plus: bucket("past_due_91_180").plus(bucket("past_due_over_180")),
  };
  const overdue1 = aging.days_1_30.plus(aging.days_31_60).plus(aging.days_61_90).plus(aging.days_91_plus);
  const overdue30 = aging.days_31_60.plus(aging.days_61_90).plus(aging.days_91_plus);
  const overdue90 = aging.days_91_plus;
  for (const title of input.titles) {
    for (const field of ["originalAmount", "defaultedBalance", "recoveredInPeriod", "dilutionInPeriod", "repurchasedInPeriod", "substitutedInPeriod"] as const) {
      requireNonNegative(field, title[field]);
    }
  }
  const defaulted = sum(input.titles.map((title) => title.defaultedBalance));
  const recovered = sum(input.titles.map((title) => title.recoveredInPeriod));
  const dilution = sum(input.titles.map((title) => title.dilutionInPeriod));
  const repurchase = sum(input.titles.map((title) => title.repurchasedInPeriod));
  const substitution = sum(input.titles.map((title) => title.substitutedInPeriod));
  const originated = sum(input.titles.map((title) => title.originalAmount));
  const netLoss = Decimal.max(defaulted.minus(recovered), ZERO);
  const ratios = {
    delinquency1Share: safeRatio(overdue1, total),
    delinquency30Share: safeRatio(overdue30, total),
    delinquency90Share: safeRatio(overdue90, total),
    grossDefaultRate: safeRatio(defaulted, originated),
    netLossRate: safeRatio(netLoss, originated),
    recoveryRate: safeRatio(recovered, defaulted),
    dilutionRate: safeRatio(dilution, originated),
    repurchaseRate: safeRatio(repurchase, originated),
    substitutionRate: safeRatio(substitution, originated),
  };
  return {
    version: receivablesPoolKernelsVersion,
    basis: "reported_title_aggregates",
    aging: {
      current: full(aging.current),
      days_1_30: full(aging.days_1_30),
      days_31_60: full(aging.days_31_60),
      days_61_90: full(aging.days_61_90),
      days_91_plus: full(aging.days_91_plus),
    },
    amounts: {
      totalOutstanding: full(total),
      overdue1Plus: full(overdue1),
      overdue30Plus: full(overdue30),
      overdue90Plus: full(overdue90),
      originated: full(originated),
      defaulted: full(defaulted),
      recovered: full(recovered),
      netLoss: full(netLoss),
      dilution: full(dilution),
      repurchase: full(repurchase),
      substitution: full(substitution),
    },
    ratios: Object.fromEntries(Object.entries(ratios).map(([key, value]) => [key, full(value)])) as ReceivablesPoolPerformance["ratios"],
    trace: {
      id: "receivables.pool_performance",
      formula: "delinquencyN = overdue over N days / totalOutstanding; grossDefault = defaulted / originated; netLoss = max(defaulted - recovered, 0) / originated; recovery = recovered / defaulted; dilution, repurchase and substitution over originated; zero denominator gives zero",
      operands: {
        totalOutstanding: full(total),
        originated: full(originated),
        defaulted: full(defaulted),
        recovered: full(recovered),
        overdue1Plus: full(overdue1),
        overdue30Plus: full(overdue30),
        overdue90Plus: full(overdue90),
        titles: String(input.titles.length),
      },
      result: full(ratios.delinquency30Share),
    },
  };
}

export type ReceivablesPoolEvidenceTitle = {
  outstandingBalance: string;
  evidenceVerified: boolean;
  anchorVerified: boolean;
  registration: "registered" | "not_required" | "missing" | "conflict";
  assignable: boolean;
  encumbrance: "free" | "pledged" | "assigned" | "unknown";
};

export type ReceivablesPoolEvidenceCoverage = {
  version: typeof receivablesPoolKernelsVersion;
  amounts: {
    totalOutstanding: string;
    verifiedBalance: string;
    anchoredBalance: string;
    registrationCoveredBalance: string;
    assignableBalance: string;
    freeBalance: string;
  };
  shares: {
    verifiedBalanceShare: string;
    anchoredBalanceShare: string;
    registrationCoverageShare: string;
    assignableBalanceShare: string;
    freeBalanceShare: string;
  };
  trace: ReceivablesPoolKernelTrace;
};

/**
 * Shares of the outstanding balance backed by verified evidence, verified source anchors,
 * registration (registered or not required), assignability and freedom from encumbrance.
 * Each share uses the whole outstanding balance as denominator; a zero balance gives zero shares.
 */
export function calculateReceivablesPoolEvidenceCoverage(input: {
  totalOutstanding: string;
  titles: readonly ReceivablesPoolEvidenceTitle[];
}): ReceivablesPoolEvidenceCoverage {
  const total = requireNonNegative("totalOutstanding", input.totalOutstanding);
  for (const title of input.titles) requireNonNegative("outstandingBalance", title.outstandingBalance);
  const balanceWhere = (test: (title: ReceivablesPoolEvidenceTitle) => boolean) => sum(input.titles.filter(test).map((title) => title.outstandingBalance));
  const verified = balanceWhere((title) => title.evidenceVerified);
  const anchored = balanceWhere((title) => title.anchorVerified);
  const registrationCovered = balanceWhere((title) => title.registration === "registered" || title.registration === "not_required");
  const assignable = balanceWhere((title) => title.assignable);
  const free = balanceWhere((title) => title.encumbrance === "free");
  return {
    version: receivablesPoolKernelsVersion,
    amounts: {
      totalOutstanding: full(total),
      verifiedBalance: full(verified),
      anchoredBalance: full(anchored),
      registrationCoveredBalance: full(registrationCovered),
      assignableBalance: full(assignable),
      freeBalance: full(free),
    },
    shares: {
      verifiedBalanceShare: full(safeRatio(verified, total)),
      anchoredBalanceShare: full(safeRatio(anchored, total)),
      registrationCoverageShare: full(safeRatio(registrationCovered, total)),
      assignableBalanceShare: full(safeRatio(assignable, total)),
      freeBalanceShare: full(safeRatio(free, total)),
    },
    trace: {
      id: "receivables.pool_evidence_coverage",
      formula: "share = balance of titles meeting the condition / totalOutstanding; zero denominator gives zero",
      operands: {
        totalOutstanding: full(total),
        verifiedBalance: full(verified),
        anchoredBalance: full(anchored),
        registrationCoveredBalance: full(registrationCovered),
        assignableBalance: full(assignable),
        freeBalance: full(free),
        titles: String(input.titles.length),
      },
      result: full(safeRatio(verified, total)),
    },
  };
}

import Decimal from "decimal.js";

import {
  agingBucketForDaysPastDue,
  receivablesAgingBuckets,
  type DilutionEvent,
  type IsoDate,
  type ReceivableTitle,
  type ReceivablesAgingBucket,
  type ReceivablesUniverse,
  type RepurchaseEvent,
  type SettlementEvent,
} from "./contracts";
import {
  canonicalMetricValue,
  collectReceivablesSourceAnchors,
  measuredReceivablesMetric,
  notEvaluableReceivablesMetric,
  receivablesDaysBetween,
  receivablesMetricsFormulaVersion,
  receivablesUtcDate,
  shiftReceivablesDays,
  type MeasuredMetric,
  type MetricPeriod,
  validateReceivablesUniverse,
} from "./static-metrics";

const ZERO = new Decimal(0);
const DILUTION_REASONS: readonly DilutionEvent["reason"][] = ["return", "rebate", "discount", "credit_note", "glosa", "other"];

export const receivablesVintageHorizons = [30, 60, 90, 120, 180, 360] as const;
export type ReceivablesVintageHorizon = typeof receivablesVintageHorizons[number];
export const receivablesRollDestinations = [...receivablesAgingBuckets, "resolved"] as const;
export type ReceivablesRollDestination = typeof receivablesRollDestinations[number];

export type RollTransition = {
  amount: string;
  rate: MeasuredMetric;
};

export type RollRateRow = {
  sourceExposure: string;
  transitions: Record<ReceivablesRollDestination, RollTransition>;
};

export type MonthlyRollRate = {
  fromDate: IsoDate;
  toDate: IsoDate;
  rows: Record<ReceivablesAgingBucket, RollRateRow>;
};

export type VintageHorizonMetric = {
  unresolvedAmount: string | null;
  unresolvedShare: MeasuredMetric;
};

export type ReceivablesVintage = {
  cohortMonth: string;
  titleCount: number;
  faceValue: string;
  horizons: Record<ReceivablesVintageHorizon, VintageHorizonMetric>;
};

export type DynamicReceivablesMetrics = {
  version: typeof receivablesMetricsFormulaVersion;
  universeId: string;
  rollRates: {
    status: "measured" | "not_evaluable";
    basis: "original_due_date";
    periods: readonly MonthlyRollRate[];
    warnings: readonly string[];
  };
  vintages: {
    status: "measured" | "not_evaluable";
    basis: "origination_month_and_original_due_date";
    cohorts: readonly ReceivablesVintage[];
    warnings: readonly string[];
  };
  dilution: {
    totalAmount: MeasuredMetric;
    shareOfOrigination: MeasuredMetric;
    byReason: Record<DilutionEvent["reason"], {amount: MeasuredMetric; shareOfOrigination: MeasuredMetric}>;
  };
  repurchaseAndLoss: {
    repurchasedAmount: MeasuredMetric;
    repurchaseShareOfAssigned: MeasuredMetric;
    finalWrittenOffAmount: MeasuredMetric;
    finalWrittenOffShare: MeasuredMetric;
    adjustedLossAmount: MeasuredMetric;
    adjustedLossShare: MeasuredMetric;
  };
  punctualSettlement: {
    dueTitleCount: MeasuredMetric;
    dueFaceValue: MeasuredMetric;
    punctualByCount: MeasuredMetric;
    punctualByValue: MeasuredMetric;
  };
  extensions: {
    extendedTitleCount: MeasuredMetric;
    extendedTitleShare: MeasuredMetric;
    extendedFaceValue: MeasuredMetric;
    extendedFaceShare: MeasuredMetric;
    weightedExtensionDays: MeasuredMetric;
  };
  quality: {
    warnings: readonly string[];
  };
};

type ResolutionEvent = SettlementEvent | DilutionEvent | RepurchaseEvent;

const decimal = (value: Decimal.Value) => new Decimal(value);

function sum(values: Iterable<Decimal.Value>): Decimal {
  let total = ZERO;
  for (const value of values) total = total.plus(value);
  return total;
}

function monthStart(value: IsoDate): IsoDate {
  return `${value.slice(0, 7)}-01` as IsoDate;
}

function monthEnd(value: IsoDate): IsoDate {
  const date = receivablesUtcDate(monthStart(value));
  date.setUTCMonth(date.getUTCMonth() + 1);
  date.setUTCDate(0);
  return date.toISOString().slice(0, 10) as IsoDate;
}

function nextMonthEnd(value: IsoDate): IsoDate {
  const date = receivablesUtcDate(monthStart(value));
  date.setUTCMonth(date.getUTCMonth() + 2);
  date.setUTCDate(0);
  return date.toISOString().slice(0, 10) as IsoDate;
}

function monthEndsBetween(startDate: IsoDate, reportingDate: IsoDate): IsoDate[] {
  const values: IsoDate[] = [];
  let cursor = monthEnd(startDate);
  while (cursor <= reportingDate) {
    values.push(cursor);
    cursor = nextMonthEnd(cursor);
  }
  return values;
}

function eventMap(universe: ReceivablesUniverse): Map<string, ResolutionEvent[]> {
  const byTitle = new Map<string, ResolutionEvent[]>();
  for (const event of [...universe.settlements, ...universe.dilutions, ...universe.repurchases]) {
    const events = byTitle.get(event.receivableId) ?? [];
    events.push(event);
    byTitle.set(event.receivableId, events);
  }
  for (const events of byTitle.values()) {
    events.sort((left, right) => left.date.localeCompare(right.date) || left.id.localeCompare(right.id));
  }
  return byTitle;
}

function outstandingAt(title: ReceivableTitle, events: readonly ResolutionEvent[], date: IsoDate): Decimal {
  if (title.issueDate > date) return ZERO;
  const resolved = sum(events.filter((event) => event.date <= date).map((event) => event.amount));
  return Decimal.max(decimal(title.faceValue).minus(resolved), ZERO);
}

function bucketAt(title: ReceivableTitle, date: IsoDate): ReceivablesAgingBucket {
  return agingBucketForDaysPastDue(receivablesDaysBetween(title.originalDueDate, date));
}

function metricFactory(universe: ReceivablesUniverse, datasetHash: string) {
  const anchors = collectReceivablesSourceAnchors(universe);
  const measured = (input: Omit<Parameters<typeof measuredReceivablesMetric>[0], "datasetHash" | "anchors">) => measuredReceivablesMetric({
    ...input,
    datasetHash,
    anchors,
  });
  const unavailable = (input: Omit<Parameters<typeof notEvaluableReceivablesMetric>[0], "datasetHash" | "anchors">) => notEvaluableReceivablesMetric({
    ...input,
    datasetHash,
    anchors,
  });
  return {measured, unavailable};
}

function completeCoverage(universe: ReceivablesUniverse, keys: Array<keyof ReceivablesUniverse["eventCoverage"]>): boolean {
  return keys.every((key) => universe.eventCoverage[key].status === "complete");
}

function rollRates(
  universe: ReceivablesUniverse,
  events: Map<string, ResolutionEvent[]>,
  datasetHash: string,
): DynamicReceivablesMetrics["rollRates"] {
  const required = ["settlements", "dilutions", "repurchases"] as const;
  if (!completeCoverage(universe, [...required])) {
    return {
      status: "not_evaluable",
      basis: "original_due_date",
      periods: [],
      warnings: required.filter((key) => universe.eventCoverage[key].status !== "complete").map((key) => `${key}_coverage_incomplete`),
    };
  }
  const {measured, unavailable} = metricFactory(universe, datasetHash);
  const dates = monthEndsBetween(universe.dates.dataStartDate, universe.dates.reportingDate);
  const periods: MonthlyRollRate[] = [];
  for (let index = 0; index < dates.length - 1; index += 1) {
    const fromDate = dates[index]!;
    const toDate = dates[index + 1]!;
    const source = Object.fromEntries(receivablesAgingBuckets.map((bucket) => [bucket, ZERO])) as Record<ReceivablesAgingBucket, Decimal>;
    const transitions = Object.fromEntries(receivablesAgingBuckets.map((bucket) => [
      bucket,
      Object.fromEntries(receivablesRollDestinations.map((destination) => [destination, ZERO])) as Record<ReceivablesRollDestination, Decimal>,
    ])) as Record<ReceivablesAgingBucket, Record<ReceivablesRollDestination, Decimal>>;

    for (const title of universe.receivables) {
      const titleEvents = events.get(title.id) ?? [];
      const fromExposure = outstandingAt(title, titleEvents, fromDate);
      if (fromExposure.lte(0)) continue;
      const sourceBucket = bucketAt(title, fromDate);
      source[sourceBucket] = source[sourceBucket].plus(fromExposure);
      const toExposure = Decimal.min(outstandingAt(title, titleEvents, toDate), fromExposure);
      const resolved = fromExposure.minus(toExposure);
      if (resolved.gt(0)) transitions[sourceBucket].resolved = transitions[sourceBucket].resolved.plus(resolved);
      if (toExposure.gt(0)) {
        const destination = bucketAt(title, toDate);
        transitions[sourceBucket][destination] = transitions[sourceBucket][destination].plus(toExposure);
      }
    }

    const period: MetricPeriod = {reportingDate: universe.dates.reportingDate, startDate: fromDate, endDate: toDate};
    const rows = Object.fromEntries(receivablesAgingBuckets.map((bucket) => {
      const denominator = source[bucket];
      const cells = Object.fromEntries(receivablesRollDestinations.map((destination) => {
        const amount = transitions[bucket][destination];
        const id = `roll_rate.${fromDate}.${toDate}.${bucket}.${destination}`;
        const rate = denominator.gt(0)
          ? measured({
            id,
            value: amount.div(denominator),
            unit: "ratio",
            period,
            universe: `gross unresolved face exposure in ${bucket} at ${fromDate}`,
            formulaId: "receivables.monthly_roll_rate",
            numerator: canonicalMetricValue(amount),
            denominator: canonicalMetricValue(denominator),
            inclusions: ["original due date", "gross face exposure net of recorded resolution events"],
          })
          : unavailable({
            id,
            unit: "ratio",
            period,
            universe: `gross unresolved face exposure in ${bucket} at ${fromDate}`,
            formulaId: "receivables.monthly_roll_rate",
            warning: "source_bucket_has_zero_exposure",
          });
        return [destination, {amount: canonicalMetricValue(amount), rate}];
      })) as Record<ReceivablesRollDestination, RollTransition>;
      return [bucket, {sourceExposure: canonicalMetricValue(denominator), transitions: cells}];
    })) as Record<ReceivablesAgingBucket, RollRateRow>;
    periods.push({fromDate, toDate, rows});
  }
  return {status: "measured", basis: "original_due_date", periods, warnings: []};
}

function vintages(
  universe: ReceivablesUniverse,
  events: Map<string, ResolutionEvent[]>,
  datasetHash: string,
): DynamicReceivablesMetrics["vintages"] {
  const required = ["settlements", "dilutions", "repurchases"] as const;
  if (!completeCoverage(universe, [...required])) {
    return {
      status: "not_evaluable",
      basis: "origination_month_and_original_due_date",
      cohorts: [],
      warnings: required.filter((key) => universe.eventCoverage[key].status !== "complete").map((key) => `${key}_coverage_incomplete`),
    };
  }
  const {measured, unavailable} = metricFactory(universe, datasetHash);
  const byMonth = new Map<string, ReceivableTitle[]>();
  for (const title of universe.receivables) {
    const key = title.issueDate.slice(0, 7);
    byMonth.set(key, [...(byMonth.get(key) ?? []), title]);
  }
  const cohorts = [...byMonth.entries()].sort(([left], [right]) => left.localeCompare(right)).map(([cohortMonth, titles]) => {
    const face = sum(titles.map((title) => title.faceValue));
    const cohortStart = `${cohortMonth}-01` as IsoDate;
    const cohortEnd = monthEnd(cohortStart);
    const period: MetricPeriod = {reportingDate: universe.dates.reportingDate, startDate: cohortStart, endDate: cohortEnd};
    const horizons = Object.fromEntries(receivablesVintageHorizons.map((horizon) => {
      const fullyObserved = titles.every((title) => shiftReceivablesDays(title.originalDueDate, horizon) <= universe.dates.reportingDate);
      const id = `vintage.${cohortMonth}.unresolved_at_${horizon}_days`;
      if (!fullyObserved) {
        return [horizon, {
          unresolvedAmount: null,
          unresolvedShare: unavailable({
            id,
            unit: "ratio",
            period,
            universe: `all receivables originated in ${cohortMonth}`,
            formulaId: "receivables.vintage_unresolved_share",
            warning: "cohort_not_fully_observed_at_horizon",
          }),
        }];
      }
      const unresolved = sum(titles.map((title) => outstandingAt(
        title,
        events.get(title.id) ?? [],
        shiftReceivablesDays(title.originalDueDate, horizon),
      )));
      return [horizon, {
        unresolvedAmount: canonicalMetricValue(unresolved),
        unresolvedShare: measured({
          id,
          value: unresolved.div(face),
          unit: "ratio",
          period,
          universe: `all receivables originated in ${cohortMonth} with a complete ${horizon}-day observation window`,
          formulaId: "receivables.vintage_unresolved_share",
          numerator: canonicalMetricValue(unresolved),
          denominator: canonicalMetricValue(face),
          inclusions: ["original due date", "gross face exposure net of recorded resolution events through each title-specific horizon"],
        }),
      }];
    })) as Record<ReceivablesVintageHorizon, VintageHorizonMetric>;
    return {cohortMonth, titleCount: titles.length, faceValue: canonicalMetricValue(face), horizons};
  });
  return {
    status: "measured",
    basis: "origination_month_and_original_due_date",
    cohorts,
    warnings: ["unresolved-at-horizon is a non-payment survival curve, not a write-off event series"],
  };
}

export function calculateDynamicReceivablesMetrics(
  universe: ReceivablesUniverse,
  options: {datasetHash: string},
): DynamicReceivablesMetrics {
  if (!/^[a-f0-9]{64}$/i.test(options.datasetHash)) throw new RangeError("dataset hash must be a SHA-256 hex digest");
  const qualityWarnings = validateReceivablesUniverse(universe);
  const {measured, unavailable} = metricFactory(universe, options.datasetHash);
  const events = eventMap(universe);
  const allPeriod: MetricPeriod = {
    reportingDate: universe.dates.reportingDate,
    startDate: universe.dates.dataStartDate,
    endDate: universe.dates.reportingDate,
  };
  const totalFace = sum(universe.receivables.map((title) => title.faceValue));
  const dilutionAmount = sum(universe.dilutions.map((event) => event.amount));
  const repurchasedAmount = sum(universe.repurchases.map((event) => event.amount));
  const writtenOffAmount = sum(universe.receivables
    .filter((title) => title.status === "written_off")
    .map((title) => outstandingAt(title, events.get(title.id) ?? [], universe.dates.reportingDate)));
  const adjustedLossAmount = writtenOffAmount.plus(repurchasedAmount);
  const dilutionMeasured = universe.eventCoverage.dilutions.status === "complete";
  const repurchasesMeasured = universe.eventCoverage.repurchases.status === "complete";
  const baseMetric = (id: string, value: Decimal, unit: MeasuredMetric["unit"], formulaId: string, universeLabel: string) => measured({
    id,
    value,
    unit,
    period: allPeriod,
    universe: universeLabel,
    formulaId,
  });
  const ratioMetric = (id: string, numerator: Decimal, denominator: Decimal, formulaId: string, universeLabel: string) => denominator.gt(0)
    ? measured({
      id,
      value: numerator.div(denominator),
      unit: "ratio",
      period: allPeriod,
      universe: universeLabel,
      formulaId,
      numerator: canonicalMetricValue(numerator),
      denominator: canonicalMetricValue(denominator),
    })
    : unavailable({id, unit: "ratio", period: allPeriod, universe: universeLabel, formulaId, warning: "denominator_unavailable"});

  const dilutionUnavailable = (id: string, unit: MeasuredMetric["unit"], formulaId: string) => unavailable({
    id,
    unit,
    period: allPeriod,
    universe: "dilution events over the declared data interval",
    formulaId,
    warning: "dilution_event_coverage_incomplete",
  });
  const byReason = Object.fromEntries(DILUTION_REASONS.map((reason) => {
    const amount = sum(universe.dilutions.filter((event) => event.reason === reason).map((event) => event.amount));
    return [reason, {
      amount: dilutionMeasured
        ? baseMetric(`dilution.${reason}.amount`, amount, "BRL", "receivables.dilution_by_reason", `dilution events classified as ${reason}`)
        : dilutionUnavailable(`dilution.${reason}.amount`, "BRL", "receivables.dilution_by_reason"),
      shareOfOrigination: dilutionMeasured
        ? ratioMetric(`dilution.${reason}.share_of_origination`, amount, totalFace, "receivables.dilution_share", `dilution events classified as ${reason} divided by gross origination`)
        : dilutionUnavailable(`dilution.${reason}.share_of_origination`, "ratio", "receivables.dilution_share"),
    }];
  })) as DynamicReceivablesMetrics["dilution"]["byReason"];

  const dueTitles = universe.receivables.filter((title) => title.originalDueDate <= universe.dates.reportingDate);
  const dueFace = sum(dueTitles.map((title) => title.faceValue));
  const punctualTitles = completeCoverage(universe, ["settlements", "dilutions", "repurchases"])
    ? dueTitles.filter((title) => outstandingAt(title, events.get(title.id) ?? [], title.originalDueDate).lte(0))
    : [];
  const punctualFace = sum(punctualTitles.map((title) => title.faceValue));
  const punctualMeasured = completeCoverage(universe, ["settlements", "dilutions", "repurchases"]);
  const punctualUnavailable = (id: string, unit: MeasuredMetric["unit"]) => unavailable({
    id,
    unit,
    period: allPeriod,
    universe: "receivables whose original due date falls on or before the reporting date",
    formulaId: "receivables.punctual_settlement",
    warning: "resolution_event_coverage_incomplete",
  });

  const extendedIds = new Set(universe.extensions.map((event) => event.receivableId));
  const extendedTitles = universe.receivables.filter((title) => extendedIds.has(title.id));
  const extendedFace = sum(extendedTitles.map((title) => title.faceValue));
  const extensionDaysNumerator = sum(universe.extensions.map((event) => {
    const title = universe.receivables.find((candidate) => candidate.id === event.receivableId);
    return title === undefined ? ZERO : decimal(title.faceValue).mul(receivablesDaysBetween(event.previousDueDate, event.newDueDate));
  }));
  const extensionObservable = universe.eventCoverage.extensions.status !== "not_provided";
  const extensionMetric = (id: string, value: Decimal, unit: MeasuredMetric["unit"], formulaId: string, numerator?: string, denominator?: string) => extensionObservable
    ? measured({
      id,
      value,
      unit,
      period: allPeriod,
      universe: "receivables with an identified change from original to current due date",
      formulaId,
      ...(numerator === undefined ? {} : {numerator}),
      ...(denominator === undefined ? {} : {denominator}),
      warnings: universe.eventCoverage.extensions.limitations,
    })
    : unavailable({id, unit, period: allPeriod, universe: "receivables with an identified change from original to current due date", formulaId, warning: "extension_event_coverage_unavailable"});

  const assignmentEvents = universe.assignmentsAndLiens
    .filter((item) => item.kind === "assignment" || item.kind === "fiduciary_assignment");
  const assignmentDenominatorMeasured = universe.eventCoverage.assignmentsAndLiens.status === "complete"
    && assignmentEvents.every((item) => item.amount !== null);
  const assignedAmount = sum(assignmentEvents.map((item) => item.amount ?? "0"));
  const repurchaseUnavailable = (id: string, unit: MeasuredMetric["unit"], warning: string) => unavailable({
    id,
    unit,
    period: allPeriod,
    universe: "repurchase events over the declared data interval",
    formulaId: "receivables.repurchase",
    warning,
  });

  return {
    version: receivablesMetricsFormulaVersion,
    universeId: universe.id,
    rollRates: rollRates(universe, events, options.datasetHash),
    vintages: vintages(universe, events, options.datasetHash),
    dilution: {
      totalAmount: dilutionMeasured ? baseMetric("dilution.total_amount", dilutionAmount, "BRL", "receivables.dilution_amount", "all recorded dilution events") : dilutionUnavailable("dilution.total_amount", "BRL", "receivables.dilution_amount"),
      shareOfOrigination: dilutionMeasured ? ratioMetric("dilution.share_of_origination", dilutionAmount, totalFace, "receivables.dilution_share", "all recorded dilution events divided by gross origination") : dilutionUnavailable("dilution.share_of_origination", "ratio", "receivables.dilution_share"),
      byReason,
    },
    repurchaseAndLoss: {
      repurchasedAmount: repurchasesMeasured ? baseMetric("repurchase.amount", repurchasedAmount, "BRL", "receivables.repurchase_amount", "all recorded repurchase events") : repurchaseUnavailable("repurchase.amount", "BRL", "repurchase_event_coverage_incomplete"),
      repurchaseShareOfAssigned: !repurchasesMeasured
        ? repurchaseUnavailable("repurchase.share_of_assigned", "ratio", "repurchase_event_coverage_incomplete")
        : !assignmentDenominatorMeasured || assignedAmount.lte(0)
          ? repurchaseUnavailable("repurchase.share_of_assigned", "ratio", "assigned_volume_denominator_unavailable_or_incomplete")
          : ratioMetric("repurchase.share_of_assigned", repurchasedAmount, assignedAmount, "receivables.repurchase_share", "repurchased amount divided by assigned volume"),
      finalWrittenOffAmount: baseMetric("loss.final_written_off_amount", writtenOffAmount, "BRL", "receivables.final_written_off_amount", "unresolved amount of receivables with final status written_off at the reporting date"),
      finalWrittenOffShare: ratioMetric("loss.final_written_off_share", writtenOffAmount, totalFace, "receivables.final_written_off_share", "unresolved written-off amount divided by gross origination"),
      adjustedLossAmount: repurchasesMeasured
        ? baseMetric("loss.adjusted_amount", adjustedLossAmount, "BRL", "receivables.adjusted_loss_amount", "unresolved written-off amount plus recorded repurchases")
        : repurchaseUnavailable("loss.adjusted_amount", "BRL", "repurchase_event_coverage_incomplete"),
      adjustedLossShare: repurchasesMeasured
        ? ratioMetric("loss.adjusted_share", adjustedLossAmount, totalFace, "receivables.adjusted_loss_share", "unresolved written-off amount plus recorded repurchases divided by gross origination")
        : repurchaseUnavailable("loss.adjusted_share", "ratio", "repurchase_event_coverage_incomplete"),
    },
    punctualSettlement: {
      dueTitleCount: baseMetric("punctual.due_title_count", decimal(dueTitles.length), "count", "receivables.due_title_count", "receivables whose original due date falls on or before the reporting date"),
      dueFaceValue: baseMetric("punctual.due_face_value", dueFace, "BRL", "receivables.due_face_value", "receivables whose original due date falls on or before the reporting date"),
      punctualByCount: punctualMeasured
        ? ratioMetric("punctual.by_count", decimal(punctualTitles.length), decimal(dueTitles.length), "receivables.punctual_settlement_count", "titles fully resolved by their original due date divided by titles due")
        : punctualUnavailable("punctual.by_count", "ratio"),
      punctualByValue: punctualMeasured
        ? ratioMetric("punctual.by_value", punctualFace, dueFace, "receivables.punctual_settlement_value", "face value fully resolved by original due date divided by due face value")
        : punctualUnavailable("punctual.by_value", "ratio"),
    },
    extensions: {
      extendedTitleCount: extensionMetric("extensions.title_count", decimal(extendedTitles.length), "count", "receivables.extension_count"),
      extendedTitleShare: extensionMetric("extensions.title_share", decimal(extendedTitles.length).div(universe.receivables.length), "ratio", "receivables.extension_title_share", String(extendedTitles.length), String(universe.receivables.length)),
      extendedFaceValue: extensionMetric("extensions.face_value", extendedFace, "BRL", "receivables.extension_face_value"),
      extendedFaceShare: extensionMetric("extensions.face_share", extendedFace.div(totalFace), "ratio", "receivables.extension_face_share", canonicalMetricValue(extendedFace), canonicalMetricValue(totalFace)),
      weightedExtensionDays: extensionMetric("extensions.weighted_days", extendedFace.gt(0) ? extensionDaysNumerator.div(extendedFace) : ZERO, "days", "receivables.weighted_extension_days", canonicalMetricValue(extensionDaysNumerator), canonicalMetricValue(extendedFace)),
    },
    quality: {
      warnings: [...new Set([
        ...qualityWarnings,
        ...(universe.eventCoverage.extensions.status === "partial" ? ["extension timing series cannot be calculated"] : []),
        ...(DILUTION_REASONS.filter((reason) => reason !== "other").every((reason) => universe.dilutions.every((event) => event.reason !== reason)) ? ["dilution causes are unclassified at title level"] : []),
      ])],
    },
  };
}

import {decimal, full, receivablesPoolKernelsVersion, type ReceivablesPoolKernelTrace} from "./pool-shared";

export type ReceivablesPoolTriggerComparison = "maximum" | "minimum";
export type ReceivablesPoolTriggerConsequence = "block" | "remediate";

export type ReceivablesPoolTrigger = {
  version: typeof receivablesPoolKernelsVersion;
  id: string;
  actual: string;
  threshold: string;
  comparison: ReceivablesPoolTriggerComparison;
  status: "within_limit" | "breached";
  consequence: ReceivablesPoolTriggerConsequence;
  /** Distance to the limit with the sign of the comparison: negative when breached. */
  headroom: string;
  trace: ReceivablesPoolKernelTrace;
};

/**
 * Compares a measured value with a declared limit. A maximum is breached strictly above the
 * threshold, a minimum strictly below it; a value exactly at the limit is within it.
 */
export function compareReceivablesPoolTrigger(input: {
  id: string;
  actual: string;
  threshold: string;
  comparison: ReceivablesPoolTriggerComparison;
  consequence: ReceivablesPoolTriggerConsequence;
}): ReceivablesPoolTrigger {
  if (!/^[a-z][a-z0-9_]*$/.test(input.id)) throw new RangeError(`trigger id must be a snake_case identifier: ${input.id}`);
  const actual = decimal(input.actual);
  const threshold = decimal(input.threshold);
  if (!actual.isFinite() || !threshold.isFinite()) throw new RangeError(`trigger ${input.id} needs finite actual and threshold values`);
  const breached = input.comparison === "maximum" ? actual.gt(threshold) : actual.lt(threshold);
  const headroom = input.comparison === "maximum" ? threshold.minus(actual) : actual.minus(threshold);
  return {
    version: receivablesPoolKernelsVersion,
    id: input.id,
    actual: full(actual),
    threshold: full(threshold),
    comparison: input.comparison,
    status: breached ? "breached" : "within_limit",
    consequence: input.consequence,
    headroom: full(headroom),
    trace: {
      id: "receivables.pool_trigger",
      formula: input.comparison === "maximum" ? "breached when actual > threshold; headroom = threshold - actual" : "breached when actual < threshold; headroom = actual - threshold",
      operands: {trigger: input.id, actual: full(actual), threshold: full(threshold), comparison: input.comparison, consequence: input.consequence},
      result: breached ? "breached" : "within_limit",
    },
  };
}

import Decimal from "decimal.js";

import {
  agingBucketForDaysPastDue,
  receivablesAgingBuckets,
  type IsoDate,
  type MeasuredProvenance,
  type ReceivablesAgingBucket,
  type ReceivablesUniverse,
  type SourceAnchor,
} from "./contracts";

const ZERO = new Decimal(0);
const DAY_MS = 86_400_000;
export const receivablesMetricsFormulaVersion = "2026.08.27-v1";

export type MetricPeriod = {
  reportingDate: IsoDate;
  startDate: IsoDate;
  endDate: IsoDate;
};

export type MeasuredMetric = {
  id: string;
  value: string | null;
  status: "measured" | "not_evaluable";
  unit: "BRL" | "count" | "days" | "ratio";
  period: MetricPeriod;
  provenance: MeasuredProvenance;
  warnings: readonly string[];
};

export type ConcentrationCut = "top_1" | "top_5" | "top_10" | "top_50";
export type ConcentrationMetrics = Record<ConcentrationCut, MeasuredMetric> & {herfindahl: MeasuredMetric};

export type StaticReceivablesMetrics = {
  version: typeof receivablesMetricsFormulaVersion;
  universeId: string;
  portfolio: {
    titleCount: MeasuredMetric;
    totalFaceValue: MeasuredMetric;
    trailing365Origination: MeasuredMetric;
    averageTicket: MeasuredMetric;
    totalOpenValue: MeasuredMetric;
    weightedOriginalTermDays: MeasuredMetric;
    weightedCurrentTermDays: MeasuredMetric;
    weightedRemainingTermDays: MeasuredMetric;
    simpleDsoDays: MeasuredMetric;
    countbackDsoDays: MeasuredMetric;
  };
  aging: Record<ReceivablesAgingBucket, MeasuredMetric>;
  concentration: {
    trailing365ByObligor: ConcentrationMetrics;
    trailing365ByEconomicGroup: ConcentrationMetrics;
    openByObligor: ConcentrationMetrics;
    openByEconomicGroup: ConcentrationMetrics;
  };
  quality: {
    warnings: readonly string[];
  };
};

const decimal = (value: Decimal.Value) => new Decimal(value);
export const canonicalMetricValue = (value: Decimal) => value.toDecimalPlaces(8).toFixed();

export function receivablesUtcDate(value: IsoDate): Date {
  const date = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(date.valueOf()) || date.toISOString().slice(0, 10) !== value) {
    throw new RangeError(`invalid ISO date: ${value}`);
  }
  return date;
}

export function receivablesDaysBetween(from: IsoDate, to: IsoDate): number {
  return Math.floor((receivablesUtcDate(to).valueOf() - receivablesUtcDate(from).valueOf()) / DAY_MS);
}

export function shiftReceivablesDays(value: IsoDate, days: number): IsoDate {
  const date = receivablesUtcDate(value);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10) as IsoDate;
}

function sum(values: Iterable<Decimal.Value>): Decimal {
  let total = ZERO;
  for (const value of values) total = total.plus(value);
  return total;
}

function safeRatio(numerator: Decimal, denominator: Decimal, label: string): Decimal {
  if (denominator.lte(0)) throw new RangeError(`${label} denominator must be positive`);
  return numerator.div(denominator);
}

export function collectReceivablesSourceAnchors(universe: ReceivablesUniverse): SourceAnchor[] {
  const unique = new Map<string, SourceAnchor>();
  const add = (anchor: SourceAnchor) => {
    if (anchor.kind === "file") {
      const key = `file:${anchor.fileId}:${anchor.fileHash}`;
      unique.set(key, {kind: "file", fileId: anchor.fileId, fileHash: anchor.fileHash});
    } else if (anchor.kind === "document") {
      const key = `document:${anchor.documentId}:${anchor.documentHash ?? ""}`;
      unique.set(key, anchor);
    } else {
      const key = `event:${anchor.sourceSystem}:${anchor.eventId}`;
      unique.set(key, anchor);
    }
  };
  universe.receivables.forEach((item) => add(item.source));
  universe.settlements.forEach((item) => add(item.source));
  universe.dilutions.forEach((item) => add(item.source));
  universe.extensions.forEach((item) => add(item.source));
  universe.repurchases.forEach((item) => add(item.source));
  universe.assignmentsAndLiens.forEach((item) => add(item.source));
  const sortKey = (anchor: SourceAnchor) => {
    if (anchor.kind === "file") return `file:${anchor.fileId}:${anchor.fileHash}`;
    if (anchor.kind === "document") return `document:${anchor.documentId}:${anchor.documentHash ?? ""}`;
    return `event:${anchor.sourceSystem}:${anchor.eventId}`;
  };
  return [...unique.values()].sort((left, right) => sortKey(left).localeCompare(sortKey(right)));
}

export function measuredReceivablesMetric(input: {
  id: string;
  value: Decimal;
  unit: MeasuredMetric["unit"];
  period: MetricPeriod;
  datasetHash: string;
  anchors: readonly SourceAnchor[];
  universe: string;
  formulaId: string;
  numerator?: string;
  denominator?: string;
  inclusions?: readonly string[];
  exclusions?: readonly string[];
  warnings?: readonly string[];
}): MeasuredMetric {
  return {
    id: input.id,
    value: canonicalMetricValue(input.value),
    status: "measured",
    unit: input.unit,
    period: input.period,
    provenance: {
      kind: "measured",
      datasetHash: input.datasetHash,
      anchors: input.anchors,
      universe: input.universe,
      reportingDate: input.period.reportingDate,
      inclusions: input.inclusions ?? [],
      exclusions: input.exclusions ?? [],
      formula: {id: input.formulaId, version: receivablesMetricsFormulaVersion},
      ...(input.numerator === undefined ? {} : {numerator: input.numerator}),
      ...(input.denominator === undefined ? {} : {denominator: input.denominator}),
      unit: input.unit,
      rounding: "Decimal ROUND_HALF_UP, maximum 8 decimal places; presentation rounding is separate",
    },
    warnings: input.warnings ?? [],
  };
}

export function notEvaluableReceivablesMetric(input: {
  id: string;
  unit: MeasuredMetric["unit"];
  period: MetricPeriod;
  datasetHash: string;
  anchors: readonly SourceAnchor[];
  universe: string;
  formulaId: string;
  warning: string;
}): MeasuredMetric {
  const measured = measuredReceivablesMetric({...input, value: ZERO, warnings: [input.warning]});
  return {...measured, value: null, status: "not_evaluable"};
}

export function validateReceivablesUniverse(universe: ReceivablesUniverse): readonly string[] {
  const warnings: string[] = [];
  const ids = new Set<string>();
  const obligorIds = new Set(universe.obligors.map((item) => item.id));
  const groupIds = new Set(universe.economicGroups.map((item) => item.id));
  const currencies = new Set<string>();
  let earliestIssue: IsoDate | undefined;
  let latestIssue: IsoDate | undefined;

  if (universe.receivables.length === 0) throw new RangeError("receivables universe cannot be empty");
  receivablesUtcDate(universe.dates.reportingDate);
  receivablesUtcDate(universe.dates.latestOriginationDate);
  receivablesUtcDate(universe.dates.dataStartDate);
  receivablesUtcDate(universe.dates.dataEndDate);
  if (universe.dates.dataStartDate > universe.dates.dataEndDate) throw new RangeError("data start date cannot follow data end date");

  for (const [eventType, coverage] of Object.entries(universe.eventCoverage)) {
    if (coverage.basis.trim().length === 0) throw new RangeError(`${eventType} coverage basis is required`);
    if (coverage.status === "not_provided") {
      if (coverage.startDate !== null || coverage.endDate !== null) {
        throw new RangeError(`${eventType} coverage dates must be null when data was not provided`);
      }
      warnings.push(`${eventType}_events_not_provided`);
      continue;
    }
    if (coverage.startDate === null || coverage.endDate === null) {
      throw new RangeError(`${eventType} coverage interval is required`);
    }
    receivablesUtcDate(coverage.startDate);
    receivablesUtcDate(coverage.endDate);
    if (coverage.startDate > coverage.endDate) throw new RangeError(`${eventType} coverage interval is invalid`);
    if (coverage.status === "complete"
      && (coverage.startDate > universe.dates.dataStartDate || coverage.endDate < universe.dates.reportingDate)) {
      throw new RangeError(`${eventType} complete coverage must span the declared history through the reporting date`);
    }
    if (coverage.status === "partial") warnings.push(`${eventType}_events_partially_covered`);
    warnings.push(...coverage.limitations.map((limitation) => `${eventType}:${limitation}`));
  }

  for (const item of universe.receivables) {
    if (ids.has(item.id)) throw new RangeError(`duplicate receivable id: ${item.id}`);
    ids.add(item.id);
    currencies.add(item.currency);
    if (!obligorIds.has(item.obligorId)) throw new RangeError(`unknown obligor ${item.obligorId} on receivable ${item.id}`);
    if (item.economicGroupId !== undefined && !groupIds.has(item.economicGroupId)) {
      throw new RangeError(`unknown economic group ${item.economicGroupId} on receivable ${item.id}`);
    }
    if (item.issueDate > item.originalDueDate) throw new RangeError(`original due date precedes issue date on receivable ${item.id}`);
    if (item.issueDate > item.currentDueDate) throw new RangeError(`current due date precedes issue date on receivable ${item.id}`);
    const face = decimal(item.faceValue);
    const open = decimal(item.openValue);
    if (face.lte(0)) throw new RangeError(`face value must be positive on receivable ${item.id}`);
    if (open.lt(0) || open.gt(face)) throw new RangeError(`open value must be between zero and face value on receivable ${item.id}`);
    if (item.status !== "open" && !open.isZero()) throw new RangeError(`non-open receivable ${item.id} cannot retain open value`);
    if (item.issueDate < universe.dates.dataStartDate || item.issueDate > universe.dates.dataEndDate) {
      throw new RangeError(`receivable ${item.id} falls outside the declared data interval`);
    }
    earliestIssue = earliestIssue === undefined || item.issueDate < earliestIssue ? item.issueDate : earliestIssue;
    latestIssue = latestIssue === undefined || item.issueDate > latestIssue ? item.issueDate : latestIssue;
  }

  const titleById = new Map(universe.receivables.map((item) => [item.id, item]));
  const eventIds = new Set<string>();
  const validateEventId = (id: string) => {
    if (eventIds.has(id)) throw new RangeError(`duplicate performance event id: ${id}`);
    eventIds.add(id);
  };
  const resolvedByTitle = new Map<string, Decimal>();
  const addResolution = (receivableId: string, amount: string) => {
    resolvedByTitle.set(receivableId, (resolvedByTitle.get(receivableId) ?? ZERO).plus(amount));
  };
  for (const item of universe.settlements) {
    validateEventId(item.id);
    const title = titleById.get(item.receivableId);
    if (title === undefined) throw new RangeError(`unknown receivable ${item.receivableId} on settlement ${item.id}`);
    receivablesUtcDate(item.date);
    if (item.date < title.issueDate || item.date > universe.dates.reportingDate) throw new RangeError(`settlement ${item.id} falls outside its observable lifecycle`);
    if (decimal(item.amount).lte(0)) throw new RangeError(`settlement ${item.id} amount must be positive`);
    addResolution(item.receivableId, item.amount);
  }
  for (const item of universe.dilutions) {
    validateEventId(item.id);
    const title = titleById.get(item.receivableId);
    if (title === undefined) throw new RangeError(`unknown receivable ${item.receivableId} on dilution ${item.id}`);
    receivablesUtcDate(item.date);
    if (item.date < title.issueDate || item.date > universe.dates.reportingDate) throw new RangeError(`dilution ${item.id} falls outside its observable lifecycle`);
    if (decimal(item.amount).lte(0)) throw new RangeError(`dilution ${item.id} amount must be positive`);
    addResolution(item.receivableId, item.amount);
  }
  for (const item of universe.repurchases) {
    validateEventId(item.id);
    const title = titleById.get(item.receivableId);
    if (title === undefined) throw new RangeError(`unknown receivable ${item.receivableId} on repurchase ${item.id}`);
    receivablesUtcDate(item.date);
    if (item.date < title.issueDate || item.date > universe.dates.reportingDate) throw new RangeError(`repurchase ${item.id} falls outside its observable lifecycle`);
    if (decimal(item.amount).lte(0)) throw new RangeError(`repurchase ${item.id} amount must be positive`);
    addResolution(item.receivableId, item.amount);
  }
  for (const item of universe.extensions) {
    validateEventId(item.id);
    const title = titleById.get(item.receivableId);
    if (title === undefined) throw new RangeError(`unknown receivable ${item.receivableId} on extension ${item.id}`);
    receivablesUtcDate(item.identifiedAt);
    receivablesUtcDate(item.previousDueDate);
    receivablesUtcDate(item.newDueDate);
    if (item.date !== null) receivablesUtcDate(item.date);
    if (item.newDueDate <= item.previousDueDate) throw new RangeError(`extension ${item.id} must move the due date forward`);
  }
  for (const item of universe.assignmentsAndLiens) {
    validateEventId(item.id);
    if (!titleById.has(item.receivableId)) throw new RangeError(`unknown receivable ${item.receivableId} on assignment or lien ${item.id}`);
    receivablesUtcDate(item.effectiveDate);
    if (item.effectiveDate > universe.dates.reportingDate) throw new RangeError(`assignment or lien ${item.id} follows the reporting date`);
    if (item.amount !== null && decimal(item.amount).lte(0)) throw new RangeError(`assignment or lien ${item.id} amount must be positive when provided`);
  }
  for (const [receivableId, resolved] of resolvedByTitle) {
    const face = decimal(titleById.get(receivableId)!.faceValue);
    if (resolved.gt(face)) throw new RangeError(`performance events exceed face value on receivable ${receivableId}`);
  }
  if ([universe.eventCoverage.settlements, universe.eventCoverage.dilutions, universe.eventCoverage.repurchases]
    .every((coverage) => coverage.status === "complete")) {
    for (const title of universe.receivables) {
      const expectedResidual = Decimal.max(decimal(title.faceValue).minus(resolvedByTitle.get(title.id) ?? ZERO), ZERO);
      if (title.status === "open" && !expectedResidual.eq(title.openValue)) {
        throw new RangeError(`open value does not reconcile to complete performance events on receivable ${title.id}`);
      }
      if (title.status === "settled" && !expectedResidual.isZero()) {
        throw new RangeError(`settled receivable ${title.id} is not fully resolved by performance events`);
      }
    }
  }

  if (currencies.size !== 1 || !currencies.has(universe.currency)) throw new RangeError("all receivables must use the universe currency");
  if (earliestIssue !== universe.dates.dataStartDate) throw new RangeError("declared data start date does not match the earliest origination");
  if (latestIssue !== universe.dates.latestOriginationDate) throw new RangeError("declared latest origination date does not match the portfolio");
  if (universe.dates.dataEndDate !== universe.dates.latestOriginationDate) {
    warnings.push("data_end_date_differs_from_latest_origination_date");
  }
  if (universe.dates.reportingDate < universe.dates.latestOriginationDate) {
    throw new RangeError("reporting date cannot precede the latest origination date");
  }
  return warnings;
}

function concentrationMetrics(input: {
  idPrefix: string;
  values: Map<string, Decimal>;
  denominator: Decimal;
  period: MetricPeriod;
  datasetHash: string;
  anchors: readonly SourceAnchor[];
  universe: string;
}): ConcentrationMetrics {
  const sorted = [...input.values.values()].sort((left, right) => right.comparedTo(left));
  const cuts: Array<[ConcentrationCut, number]> = [["top_1", 1], ["top_5", 5], ["top_10", 10], ["top_50", 50]];
  if (input.denominator.lte(0)) {
    const unavailable = (suffix: string) => notEvaluableReceivablesMetric({
      id: `${input.idPrefix}.${suffix}`,
      unit: "ratio",
      period: input.period,
      datasetHash: input.datasetHash,
      anchors: input.anchors,
      universe: input.universe,
      formulaId: suffix === "herfindahl" ? "receivables.concentration.herfindahl" : "receivables.concentration.share",
      warning: "concentration_denominator_unavailable",
    });
    return {
      top_1: unavailable("top_1"),
      top_5: unavailable("top_5"),
      top_10: unavailable("top_10"),
      top_50: unavailable("top_50"),
      herfindahl: unavailable("herfindahl"),
    };
  }
  const cutMetrics = Object.fromEntries(cuts.map(([cut, count]) => {
    const numerator = sum(sorted.slice(0, count));
    return [cut, measuredReceivablesMetric({
      id: `${input.idPrefix}.${cut}`,
      value: safeRatio(numerator, input.denominator, `${input.idPrefix}.${cut}`),
      unit: "ratio",
      period: input.period,
      datasetHash: input.datasetHash,
      anchors: input.anchors,
      universe: input.universe,
      formulaId: "receivables.concentration.share",
      numerator: canonicalMetricValue(numerator),
      denominator: canonicalMetricValue(input.denominator),
      inclusions: [`largest ${count} ${input.idPrefix.includes("group") ? "economic groups" : "obligors"}`],
    })];
  })) as Record<ConcentrationCut, MeasuredMetric>;
  const herfindahl = sum([...input.values.values()].map((value) => safeRatio(value, input.denominator, `${input.idPrefix}.herfindahl`).pow(2)));
  return {
    ...cutMetrics,
    herfindahl: measuredReceivablesMetric({
      id: `${input.idPrefix}.herfindahl`,
      value: herfindahl,
      unit: "ratio",
      period: input.period,
      datasetHash: input.datasetHash,
      anchors: input.anchors,
      universe: input.universe,
      formulaId: "receivables.concentration.herfindahl",
      denominator: canonicalMetricValue(input.denominator),
    }),
  };
}

function countbackDso(universe: ReceivablesUniverse, openBalance: Decimal): Decimal {
  if (openBalance.isZero()) return ZERO;
  const byDate = new Map<IsoDate, Decimal>();
  for (const item of universe.receivables) {
    byDate.set(item.issueDate, (byDate.get(item.issueDate) ?? ZERO).plus(item.faceValue));
  }
  let remaining = openBalance;
  let days = ZERO;
  let cursor = universe.dates.reportingDate;
  while (remaining.gt(0)) {
    if (cursor < universe.dates.dataStartDate) throw new RangeError("insufficient origination history for countback DSO");
    const originated = byDate.get(cursor) ?? ZERO;
    if (originated.gt(0) && remaining.lt(originated)) {
      days = days.plus(remaining.div(originated));
      remaining = ZERO;
      break;
    }
    remaining = Decimal.max(remaining.minus(originated), ZERO);
    days = days.plus(1);
    cursor = shiftReceivablesDays(cursor, -1);
  }
  return days;
}

export function calculateStaticReceivablesMetrics(
  universe: ReceivablesUniverse,
  options: {datasetHash: string},
): StaticReceivablesMetrics {
  if (!/^[a-f0-9]{64}$/i.test(options.datasetHash)) throw new RangeError("dataset hash must be a SHA-256 hex digest");
  const qualityWarnings = validateReceivablesUniverse(universe);
  const anchors = collectReceivablesSourceAnchors(universe);
  if (anchors.length === 0) throw new RangeError("at least one source anchor is required");

  const allPeriod: MetricPeriod = {
    reportingDate: universe.dates.reportingDate,
    startDate: universe.dates.dataStartDate,
    endDate: universe.dates.dataEndDate,
  };
  const trailingStart = shiftReceivablesDays(universe.dates.reportingDate, -364);
  const trailingPeriod: MetricPeriod = {
    reportingDate: universe.dates.reportingDate,
    startDate: trailingStart,
    endDate: universe.dates.reportingDate,
  };
  const snapshotPeriod: MetricPeriod = {
    reportingDate: universe.dates.reportingDate,
    startDate: universe.dates.reportingDate,
    endDate: universe.dates.reportingDate,
  };

  const totalFace = sum(universe.receivables.map((item) => item.faceValue));
  const totalOpen = sum(universe.receivables.map((item) => item.openValue));
  const trailing = universe.receivables.filter((item) => item.issueDate >= trailingStart && item.issueDate <= universe.dates.reportingDate);
  const trailingFace = sum(trailing.map((item) => item.faceValue));
  const originalTermNumerator = sum(universe.receivables.map((item) => decimal(item.faceValue).mul(receivablesDaysBetween(item.issueDate, item.originalDueDate))));
  const currentTermNumerator = sum(universe.receivables.map((item) => decimal(item.faceValue).mul(receivablesDaysBetween(item.issueDate, item.currentDueDate))));
  const remainingTermNumerator = sum(universe.receivables.map((item) => decimal(item.openValue).mul(Math.max(0, receivablesDaysBetween(universe.dates.reportingDate, item.currentDueDate)))));
  const titleCount = decimal(universe.receivables.length);

  const metric = (input: Omit<Parameters<typeof measuredReceivablesMetric>[0], "datasetHash" | "anchors">) => measuredReceivablesMetric({
    ...input,
    datasetHash: options.datasetHash,
    anchors,
  });

  const agingValues = Object.fromEntries(receivablesAgingBuckets.map((bucket) => [bucket, ZERO])) as Record<ReceivablesAgingBucket, Decimal>;
  const openByObligor = new Map<string, Decimal>();
  const openByGroup = new Map<string, Decimal>();
  for (const item of universe.receivables) {
    const open = decimal(item.openValue);
    if (open.isZero()) continue;
    const daysPastDue = receivablesDaysBetween(item.currentDueDate, universe.dates.reportingDate);
    const bucket = agingBucketForDaysPastDue(daysPastDue);
    agingValues[bucket] = agingValues[bucket].plus(open);
    openByObligor.set(item.obligorId, (openByObligor.get(item.obligorId) ?? ZERO).plus(open));
    const groupId = item.economicGroupId ?? item.obligorId;
    openByGroup.set(groupId, (openByGroup.get(groupId) ?? ZERO).plus(open));
  }

  const trailingByObligor = new Map<string, Decimal>();
  const trailingByGroup = new Map<string, Decimal>();
  for (const item of trailing) {
    trailingByObligor.set(item.obligorId, (trailingByObligor.get(item.obligorId) ?? ZERO).plus(item.faceValue));
    const groupId = item.economicGroupId ?? item.obligorId;
    trailingByGroup.set(groupId, (trailingByGroup.get(groupId) ?? ZERO).plus(item.faceValue));
  }

  return {
    version: receivablesMetricsFormulaVersion,
    universeId: universe.id,
    portfolio: {
      titleCount: metric({id: "portfolio.title_count", value: titleCount, unit: "count", period: allPeriod, universe: "all receivables originated in the declared interval", formulaId: "receivables.count"}),
      totalFaceValue: metric({id: "portfolio.total_face_value", value: totalFace, unit: "BRL", period: allPeriod, universe: "all receivables originated in the declared interval", formulaId: "receivables.sum_face_value"}),
      trailing365Origination: metric({id: "portfolio.trailing_365_origination", value: trailingFace, unit: "BRL", period: trailingPeriod, universe: "receivables originated during the inclusive trailing 365-day interval", formulaId: "receivables.trailing_365_origination"}),
      averageTicket: metric({id: "portfolio.average_ticket", value: safeRatio(totalFace, titleCount, "average ticket"), unit: "BRL", period: allPeriod, universe: "all receivables originated in the declared interval", formulaId: "receivables.average_ticket", numerator: canonicalMetricValue(totalFace), denominator: canonicalMetricValue(titleCount)}),
      totalOpenValue: metric({id: "portfolio.total_open_value", value: totalOpen, unit: "BRL", period: snapshotPeriod, universe: "open receivable balance at the reporting date", formulaId: "receivables.sum_open_value"}),
      weightedOriginalTermDays: metric({id: "portfolio.weighted_original_term_days", value: safeRatio(originalTermNumerator, totalFace, "weighted original term"), unit: "days", period: allPeriod, universe: "all receivables originated in the declared interval", formulaId: "receivables.weighted_original_term", numerator: canonicalMetricValue(originalTermNumerator), denominator: canonicalMetricValue(totalFace)}),
      weightedCurrentTermDays: metric({id: "portfolio.weighted_current_term_days", value: safeRatio(currentTermNumerator, totalFace, "weighted current term"), unit: "days", period: allPeriod, universe: "all receivables originated in the declared interval", formulaId: "receivables.weighted_current_term", numerator: canonicalMetricValue(currentTermNumerator), denominator: canonicalMetricValue(totalFace)}),
      weightedRemainingTermDays: metric({id: "portfolio.weighted_remaining_term_days", value: totalOpen.isZero() ? ZERO : remainingTermNumerator.div(totalOpen), unit: "days", period: snapshotPeriod, universe: "open receivable balance at the reporting date", formulaId: "receivables.weighted_remaining_term", numerator: canonicalMetricValue(remainingTermNumerator), denominator: canonicalMetricValue(totalOpen)}),
      simpleDsoDays: trailingFace.lte(0)
        ? notEvaluableReceivablesMetric({id: "portfolio.simple_dso_days", unit: "days", period: trailingPeriod, datasetHash: options.datasetHash, anchors, universe: "open balance divided by trailing 365-day origination", formulaId: "receivables.simple_dso", warning: "trailing_365_origination_unavailable"})
        : metric({id: "portfolio.simple_dso_days", value: totalOpen.mul(365).div(trailingFace), unit: "days", period: trailingPeriod, universe: "open balance divided by trailing 365-day origination", formulaId: "receivables.simple_dso", numerator: canonicalMetricValue(totalOpen.mul(365)), denominator: canonicalMetricValue(trailingFace)}),
      countbackDsoDays: metric({id: "portfolio.countback_dso_days", value: countbackDso(universe, totalOpen), unit: "days", period: allPeriod, universe: "daily origination consumed backwards from the reporting date until the open balance is covered", formulaId: "receivables.daily_countback_dso", numerator: canonicalMetricValue(totalOpen), denominator: "daily origination series"}),
    },
    aging: Object.fromEntries(receivablesAgingBuckets.map((bucket) => [bucket, metric({
      id: `aging.${bucket}`,
      value: agingValues[bucket],
      unit: "BRL",
      period: snapshotPeriod,
      universe: "open receivable balance at the reporting date",
      formulaId: "receivables.aging.seven_bucket",
      inclusions: [bucket],
    })])) as Record<ReceivablesAgingBucket, MeasuredMetric>,
    concentration: {
      trailing365ByObligor: concentrationMetrics({idPrefix: "concentration.trailing_365.obligor", values: trailingByObligor, denominator: trailingFace, period: trailingPeriod, datasetHash: options.datasetHash, anchors, universe: "receivables originated during the inclusive trailing 365-day interval"}),
      trailing365ByEconomicGroup: concentrationMetrics({idPrefix: "concentration.trailing_365.economic_group", values: trailingByGroup, denominator: trailingFace, period: trailingPeriod, datasetHash: options.datasetHash, anchors, universe: "receivables originated during the inclusive trailing 365-day interval, consolidated by economic group"}),
      openByObligor: concentrationMetrics({idPrefix: "concentration.open.obligor", values: openByObligor, denominator: totalOpen, period: snapshotPeriod, datasetHash: options.datasetHash, anchors, universe: "open receivable balance at the reporting date"}),
      openByEconomicGroup: concentrationMetrics({idPrefix: "concentration.open.economic_group", values: openByGroup, denominator: totalOpen, period: snapshotPeriod, datasetHash: options.datasetHash, anchors, universe: "open receivable balance at the reporting date, consolidated by economic group"}),
    },
    quality: {warnings: qualityWarnings},
  };
}

